insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Count Them Up: Ten Anime and Manga in Numbers', 'count-them-up-ten-anime-and-manga-in-numbers', 'multiple_choice', '[{"question":"The Cowboy Bebop series is a single season. How many episodes, which the show calls sessions, does it have?","options":["39","26","13","24"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["cowboy-bebop-episode-count-004"],"source_url":"https://en.wikipedia.org/wiki/Cowboy_Bebop"},{"question":"How many episodes did the Death Note anime run for on Nippon Television?","options":["37","52","26","25"],"correct":0,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-anime-run-006"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Toei Animation''s 1992 Sailor Moon anime ran over five seasons. How many episodes is that in total?","options":["150","100","250","200"],"correct":3,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["sailor-moon-anime-run-008"],"source_url":"https://en.wikipedia.org/wiki/Sailor_Moon_(TV_series)"},{"question":"The first season of Fairy Tail has 175 episodes. How many does the whole TV anime reach across all its seasons?","options":["175","250","328","400"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fairy-tail-anime-total-012","fairy-tail-anime-s1-009"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail_(TV_series)"},{"question":"How many episodes did the original Gintama TV series run for on TV Tokyo, from 2006 to 2010?","options":["300","367","201","150"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-series-1-013"],"source_url":"https://en.wikipedia.org/wiki/Gintama_(TV_series)"},{"question":"The Jujutsu Kaisen manga ended in 2024. How many collected volumes does it fill?","options":["30","25","38","20"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["jujutsu-kaisen-volume-count-010"],"source_url":"https://en.wikipedia.org/wiki/Jujutsu_Kaisen"},{"question":"Over four seasons, how many episodes does the Haikyu!! TV anime have in all?","options":["100","25","85","64"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["haikyu-anime-totals-008"],"source_url":"https://en.wikipedia.org/wiki/List_of_Haikyu!!_episodes"},{"question":"How many collected volumes did the Bleach manga fill?","options":["108","27","54","74"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-volume-count-004"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"},{"question":"The Attack on Titan manga closed with how many chapters?","options":["139","220","112","100"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-chapter-count-015"],"source_url":"https://ja.wikipedia.org/wiki/%E9%80%B2%E6%92%83%E3%81%AE%E5%B7%A8%E4%BA%BA"},{"question":"Vinland Saga''s manga finished with 29 volumes. How many chapters do those volumes hold?","options":["139","220","300","180"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["vinland-saga-volumes-chapters-004"],"source_url":"https://en.wikipedia.org/wiki/List_of_Vinland_Saga_chapters"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Not in That Magazine: Manga Odd One Out', 'not-in-that-magazine-manga-odd-one-out', 'intruder', '[{"question":"Three of these manga ran in Weekly Shonen Jump. Which one ran in a different magazine?","options":[{"label":"Haikyu!!"},{"label":"Death Note"},{"label":"Bleach"},{"label":"Blue Lock"}],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["blue-lock-magazine-start-003","death-note-magazine-run-003","haikyu-magazine-run-003","bleach-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Blue_Lock"},{"question":"Three of these manga ran in Weekly Shonen Magazine. Which one ran in Weekly Shonen Jump?","options":[{"label":"Blue Lock"},{"label":"Gintama"},{"label":"Fairy Tail"},{"label":"Tokyo Revengers"}],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-magazine-003","fairy-tail-magazine-003","blue-lock-magazine-start-003","tokyo-revengers-magazine-005"],"source_url":"https://en.wikipedia.org/wiki/Gintama"},{"question":"Three of these manga were published by Kodansha. Which one was published by Shogakukan?","options":[{"label":"Attack on Titan"},{"label":"Sailor Moon"},{"label":"Detective Conan"},{"label":"Fairy Tail"}],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["detective-conan-publisher-004","fairy-tail-magazine-003","attack-on-titan-magazine-publisher-013","sailor-moon-manga-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed"},{"question":"Three of these manga were published by Shueisha. Which one was published by Hakusensha?","options":[{"label":"Fruits Basket"},{"label":"Death Note"},{"label":"Gintama"},{"label":"Tokyo Ghoul"}],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-publisher-004","death-note-magazine-run-003","gintama-publisher-004","tokyo-ghoul-manga-run-003"],"source_url":"https://en.wikipedia.org/wiki/Fruits_Basket"},{"question":"Three of these ran with Shueisha''s Young Jump titles. Which one began as a webcomic on a Shogakukan site?","options":[{"label":"Oshi no Ko"},{"label":"One-Punch Man"},{"label":"Mob Psycho 100"},{"label":"Tokyo Ghoul"}],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["mob-psycho-100-manga-origin-003","oshi-no-ko-magazine-run-003","tokyo-ghoul-manga-run-003","one-punch-man-remake-magazine-004"],"source_url":"https://en.wikipedia.org/wiki/Mob_Psycho_100"},{"question":"Three of these manga started in Weekly Shonen Jump. Which one started on the Shonen Jump+ platform?","options":[{"label":"Black Clover"},{"label":"Jujutsu Kaisen"},{"label":"Kagurabachi"},{"label":"Dandadan"}],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-serialization-start-003","black-clover-magazine-004","jujutsu-kaisen-magazine-publisher-009","kagurabachi-serialization-start-003"],"source_url":"https://en.wikipedia.org/wiki/Dandadan"},{"question":"Three of these manga ran in monthly magazines. Which one ran in a weekly?","options":[{"label":"Death Note"},{"label":"Reincarnated as a Slime"},{"label":"Fullmetal Alchemist"},{"label":"Attack on Titan"}],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-magazine-run-003","fullmetal-alchemist-magazine-run-003","attack-on-titan-magazine-publisher-013","that-time-i-got-reincarnated-as-a-slime-manga-007"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Three of these manga are published by Shueisha. Which one is published by Houbunsha?","options":[{"label":"Bocchi the Rock!"},{"label":"One Piece"},{"label":"Bleach"},{"label":"Haikyu!!"}],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bocchi-the-rock-publisher-004","haikyu-magazine-run-003","bleach-magazine-run-003","one-piece-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Bocchi_the_Rock!"},{"question":"Three of these manga began serialization in the 1990s. Which one began in 2001?","options":[{"label":"Hunter x Hunter"},{"label":"Bleach"},{"label":"One Piece"},{"label":"Naruto"}],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["bleach-magazine-run-003","naruto-manga-run-004","one-piece-magazine-run-003","hunter-x-hunter-magazine-publisher-003"],"source_url":"https://en.wikipedia.org/wiki/Bleach_(manga)"},{"question":"Three of these manga ended after 2020. Which one had already ended in 2017?","options":[{"label":"Kaiju No. 8"},{"label":"Jujutsu Kaisen"},{"label":"Fairy Tail"},{"label":"Tokyo Revengers"}],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fairy-tail-manga-run-004","jujutsu-kaisen-manga-run-008","kaiju-no-8-author-run-002","tokyo-revengers-manga-run-003"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Release Race: Which Anime, Manga or Novel Came First?', 'release-race-which-anime-manga-or-novel-came-first', 'multiple_choice', '[{"question":"Which of these anime started airing first?","options":["Fairy Tail","Attack on Titan","Naruto","Detective Conan"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["detective-conan-anime-start-007","naruto-tv-naruto-006","fairy-tail-anime-s1-009","attack-on-titan-anime-premiere-016"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed_(TV_series)"},{"question":"Which of these anime had the most recent premiere?","options":["Tokyo Ghoul","Mob Psycho 100","Steins;Gate","Death Note"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-anime-run-006","steins-gate-anime-run-016","tokyo-ghoul-anime-first-season-007","mob-psycho-100-anime-season-one-012"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Which of these anime was the first to reach television?","options":["Code Geass","Cowboy Bebop","Violet Evergarden","Re:Zero"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["cowboy-bebop-tv-tokyo-run-005","code-geass-anime-r1-010","re-zero-anime-s1-007","violet-evergarden-tv-run-008"],"source_url":"https://en.wikipedia.org/wiki/List_of_Cowboy_Bebop_episodes"},{"question":"Which of these shows opened its first season earliest?","options":["Haikyu!!","One-Punch Man","Black Clover","Reincarnated as a Slime"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-anime-season-one-007","one-punch-man-anime-season-one-007","black-clover-anime-s1-007","that-time-i-got-reincarnated-as-a-slime-anime-s1-010"],"source_url":"https://en.wikipedia.org/wiki/Haikyu!!"},{"question":"Which of these shows was the last to premiere?","options":["Blue Lock","Tokyo Revengers","Jujutsu Kaisen","Demon Slayer"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["blue-lock-anime-season-one-008","demon-slayer-tv-start-008","jujutsu-kaisen-anime-premiere-012","tokyo-revengers-anime-s1-006"],"source_url":"https://en.wikipedia.org/wiki/List_of_Blue_Lock_episodes"},{"question":"Which of these manga began serialization first?","options":["Attack on Titan","Haikyu!!","Death Note","Fairy Tail"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-magazine-run-003","fairy-tail-manga-run-004","attack-on-titan-manga-run-012","haikyu-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Which of these manga began serialization most recently?","options":["Jujutsu Kaisen","Bocchi the Rock!","Chainsaw Man","Tokyo Revengers"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["chainsaw-man-manga-run-004","tokyo-revengers-manga-run-003","bocchi-the-rock-manga-start-005","jujutsu-kaisen-manga-run-008"],"source_url":"https://en.wikipedia.org/wiki/Chainsaw_Man"},{"question":"Which of these stories was put online earliest?","options":["Re:Zero","Tower of God","Reincarnated as a Slime","Omniscient Reader''s Viewpoint"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-webtoon-launch-003","re-zero-web-novel-003","that-time-i-got-reincarnated-as-a-slime-web-novel-003","omniscient-readers-viewpoint-novel-run-004"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"Which of these light novel series was printed first?","options":["Sword Art Online","Violet Evergarden","Re:Zero","Reincarnated as a Slime"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sword-art-online-novel-start-003","re-zero-light-novel-004","that-time-i-got-reincarnated-as-a-slime-light-novel-004","violet-evergarden-novel-start-005"],"source_url":"https://en.wikipedia.org/wiki/Sword_Art_Online"},{"question":"Which of these four anime was the last to premiere its first season?","options":["Frieren: Beyond Journey''s End","Oshi no Ko","The Apothecary Diaries","Dandadan"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dandadan-anime-season-one-009","oshi-no-ko-anime-season-one-008","frieren-anime-season-one-008","apothecary-diaries-anime-season-one-006"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_episodes"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Same Studio, Same Length: Anime Odd One Out', 'same-studio-same-length-anime-odd-one-out', 'intruder', '[{"question":"Three of these anime were animated by Pierrot. Which one was animated by Bones?","options":[{"label":"Mob Psycho 100"},{"label":"Tokyo Ghoul"},{"label":"Bleach"},{"label":"Black Clover"}],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["mob-psycho-100-anime-studio-007","black-clover-studio-009","tokyo-ghoul-anime-first-season-007","bleach-anime-production-007"],"source_url":"https://en.wikipedia.org/wiki/Mob_Psycho_100"},{"question":"Three of these anime had Madhouse make their first season (for Hunter x Hunter, the 2011 series). Which one was made by Production I.G?","options":[{"label":"One-Punch Man"},{"label":"Hunter x Hunter"},{"label":"Frieren: Beyond Journey''s End"},{"label":"Haikyu!!"}],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["haikyu-anime-season-one-007","one-punch-man-anime-season-one-007","frieren-anime-season-one-008","hunter-x-hunter-second-anime-2011-008"],"source_url":"https://en.wikipedia.org/wiki/Haikyu!!"},{"question":"Three of these anime came from Sunrise. Which one came from Gainax?","options":[{"label":"Neon Genesis Evangelion"},{"label":"Gintama"},{"label":"Cowboy Bebop"},{"label":"Code Geass"}],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-studio-director-002","code-geass-anime-studio-002","cowboy-bebop-studio-director-002","gintama-studios-022"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Three of these anime were animated by A-1 Pictures. Which one was animated by Science Saru?","options":[{"label":"Solo Leveling"},{"label":"Dandadan"},{"label":"Sword Art Online"},{"label":"Fairy Tail"}],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-anime-studio-director-008","sword-art-online-anime-studio-016","solo-leveling-anime-studio-009","fairy-tail-anime-studios-013"],"source_url":"https://en.wikipedia.org/wiki/Dandadan"},{"question":"Three of these anime have a 12-episode first season. Which one has 24 episodes?","options":[{"label":"Bocchi the Rock!"},{"label":"Mob Psycho 100"},{"label":"Blue Lock"},{"label":"One-Punch Man"}],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["blue-lock-anime-season-one-008","mob-psycho-100-anime-season-one-012","one-punch-man-anime-season-one-007","bocchi-the-rock-episodes-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Blue_Lock_episodes"},{"question":"Three of these anime ran 24 episodes in their first run. Which one ran only 11?","options":[{"label":"Oshi no Ko"},{"label":"Steins;Gate"},{"label":"Tokyo Revengers"},{"label":"Reincarnated as a Slime"}],"correct":0,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["oshi-no-ko-anime-season-one-008","tokyo-revengers-anime-s1-006","steins-gate-anime-run-016","that-time-i-got-reincarnated-as-a-slime-anime-s1-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_episodes"},{"question":"Three of these anime have a 25-episode first season. Which one has 13?","options":[{"label":"Attack on Titan"},{"label":"Haikyu!!"},{"label":"Re:Zero"},{"label":"Violet Evergarden"}],"correct":3,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["violet-evergarden-episodes-009","attack-on-titan-anime-premiere-016","haikyu-anime-season-one-007","re-zero-anime-s1-007"],"source_url":"https://en.wikipedia.org/wiki/Violet_Evergarden"},{"question":"Three of these anime started airing in 2022. Which one started in 2023?","options":[{"label":"Bocchi the Rock!"},{"label":"Oshi no Ko"},{"label":"Blue Lock"},{"label":"Spy x Family"}],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["oshi-no-ko-anime-season-one-008","spy-x-family-anime-run-007","bocchi-the-rock-anime-start-008","blue-lock-anime-season-one-008"],"source_url":"https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_episodes"},{"question":"Three of these anime premiered in October. Which one premiered in April?","options":[{"label":"Dandadan"},{"label":"Attack on Titan"},{"label":"Jujutsu Kaisen"},{"label":"One-Punch Man"}],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-anime-premiere-016","jujutsu-kaisen-anime-premiere-012","dandadan-anime-season-one-009","one-punch-man-anime-season-one-007"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)"},{"question":"Three of these anime started in the 2010s. Which one started in 1992?","options":[{"label":"Demon Slayer"},{"label":"Haikyu!!"},{"label":"Sailor Moon"},{"label":"Black Clover"}],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sailor-moon-anime-run-008","haikyu-anime-season-one-007","black-clover-anime-s1-007","demon-slayer-tv-start-008"],"source_url":"https://en.wikipedia.org/wiki/Sailor_Moon_(TV_series)"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Same Voice, Different Anime: Japanese Voice Actors Across Series', 'same-voice-different-anime-japanese-voice-actors-across-series', 'multiple_choice', '[{"question":"Which Japanese voice actor plays both Light Yagami in Death Note and Rintaro Okabe in Steins;Gate?","options":["Hiroshi Kamiya","Yuki Kaji","Daisuke Ono","Mamoru Miyano"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-light-voice-067","steins-gate-okabe-voice-070"],"source_url":"https://en.wikipedia.org/wiki/Death_Note_(2006_TV_series)"},{"question":"Which voice actress plays Faye Valentine in Cowboy Bebop and Rei Ayanami in Neon Genesis Evangelion?","options":["Megumi Hayashibara","Kana Hanazawa","Yui Horie","Maaya Sakamoto"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["cowboy-bebop-faye-valentine-voice-035","evangelion-rei-ayanami-voice-048"],"source_url":"https://en.wikipedia.org/wiki/List_of_Cowboy_Bebop_characters"},{"question":"Ken Kaneki in Tokyo Ghoul and Ken Takakura in Dandadan share one Japanese voice actor. Who?","options":["Kaito Ishikawa","Takuya Eguchi","Natsuki Hanae","Yoshitsugu Matsuoka"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tokyo-ghoul-ken-kaneki-voice-078","dandadan-ken-takakura-voice-071"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Ghoul_characters"},{"question":"Suzaku Kururugi in Code Geass and Arataka Reigen in Mob Psycho 100 are voiced by whom?","options":["Tomokazu Sugita","Hiroshi Kamiya","Kenjiro Tsuda","Takahiro Sakurai"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["code-geass-suzaku-kururugi-voic