insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Where Did It Begin? Origins and Adaptations Odd One Out', 'where-did-it-begin-origins-and-adaptations-odd-one-out', 'intruder', '[{"question":"Three of these stories began as web novels. Which one began as a webtoon?","options":[{"label":"Reincarnated as a Slime"},{"label":"Re:Zero"},{"label":"Tower of God"},{"label":"Solo Leveling"}],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-webtoon-launch-003","re-zero-web-novel-003","that-time-i-got-reincarnated-as-a-slime-creator-002","solo-leveling-novel-author-003"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"Three of these stories began as web novels. Which one began as a light novel that won a studio''s award?","options":[{"label":"Omniscient Reader''s Viewpoint"},{"label":"Sword Art Online"},{"label":"The Apothecary Diaries"},{"label":"Violet Evergarden"}],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["violet-evergarden-creator-002","violet-evergarden-award-novel-026","apothecary-diaries-novel-history-003","omniscient-readers-viewpoint-novel-run-004","sword-art-online-web-novel-005"],"source_url":"https://en.wikipedia.org/wiki/Violet_Evergarden"},{"question":"Three of these started as free online comics. Which one started in a print magazine?","options":[{"label":"Detective Conan"},{"label":"One-Punch Man"},{"label":"Tower of God"},{"label":"Mob Psycho 100"}],"correct":0,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["detective-conan-magazine-003","mob-psycho-100-manga-origin-003","one-punch-man-webcomic-start-003","tower-of-god-webtoon-launch-003"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed"},{"question":"Three of these were published as light novels. Which one began as a visual novel?","options":[{"label":"Sword Art Online"},{"label":"Violet Evergarden"},{"label":"Steins;Gate"},{"label":"The Apothecary Diaries"}],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["steins-gate-vn-release-003","sword-art-online-novel-start-003","violet-evergarden-novel-start-005","apothecary-diaries-novel-history-003"],"source_url":"https://en.wikipedia.org/wiki/Steins;Gate"},{"question":"Three of these have a live-action version that has been released. Which one has only had a live-action film announced, as of October 2026?","options":[{"label":"Mob Psycho 100"},{"label":"My Hero Academia"},{"label":"One Piece"},{"label":"Gintama"}],"correct":1,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["my-hero-academia-live-action-film-030","gintama-live-action-032","mob-psycho-100-live-action-015","one-piece-live-action-023"],"source_url":"https://en.wikipedia.org/wiki/My_Hero_Academia"},{"question":"Three of these stories started in South Korea. Which one started in Japan?","options":[{"label":"Tower of God"},{"label":"Re:Zero"},{"label":"Solo Leveling"},{"label":"Omniscient Reader''s Viewpoint"}],"correct":1,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["re-zero-japanese-origin-087","tower-of-god-korean-origin-046","solo-leveling-korean-origin-074","omniscient-readers-viewpoint-korean-origin-028"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero"},{"question":"Three of these light novel series were put out by publishing houses. Which one was put out by an animation studio?","options":[{"label":"Reincarnated as a Slime"},{"label":"Violet Evergarden"},{"label":"Re:Zero"},{"label":"Sword Art Online"}],"correct":1,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["violet-evergarden-publisher-004","re-zero-light-novel-004","sword-art-online-novel-start-003","that-time-i-got-reincarnated-as-a-slime-light-novel-004