insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'anime-mix' and site_id = 'anime'), 'Who Eats What? Sweet Teeth, Snacks and Appetites', 'who-eats-what-sweet-teeth-snacks-and-appetites', 'multiple_choice', '[{"question":"Ryuk, the bored death god of Death Note, has a weakness for which fruit?","options":["Apples","Grapes","Pears","Oranges"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-ryuk-apples-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Anya Forger''s best-known catchphrase says she likes which snack?","options":["Chestnuts","Almonds","Popcorn","Peanuts"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["spy-x-family-anya-peanuts-018"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)"},{"question":"The detective L is a scrawny crouching genius who eats what without end?","options":["Sweets","Fried chicken","Spicy noodles","Rice balls"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-l-habits-015"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Usagi Tsukino of Sailor Moon is a glutton for sweets, yet she is said to dislike which food?","options":["Pancakes","Carrots","Dumplings","Cake"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sailor-moon-usagi-dislikes-carrots-064","sailor-moon-usagi-cake-lover-032"],"source_url":"https://en.wikipedia.org/wiki/Sailor_Moon_(character)"},{"question":"When her money runs out because of her gear, the bassist Ryo Yamada of Bocchi the Rock! sometimes eats what?","options":["Weeds","Dry noodles","Leftover bread","Plain rice"],"correct":0,"k