insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_07'), (select id from public.groups where slug = 'attack-on-titan' and site_id = 'anime'), 'Survey Corps and Cadets: Name the Character', 'survey-corps-and-cadets-name-the-character', 'guess_from_clues', '[{"question":"Who is this?","clues":["A boy from Shiganshina","Vows to wipe out the Titans after they wreck his home","His name is written エレン・イェーガー in Japanese"],"options":["Eren Yeager","Jean Kirstein","Armin Arlert","Marco Bott"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-eren-yeager-name-031","attack-on-titan-armin-arlert-name-033","attack-on-titan-jean-kirstein-name-037","attack-on-titan-marco-bott-name-045"],"source_url":"https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters"},{"question":"Who is this?","clues":["Eren''s adoptive sister and childhood friend","A gifted fighter","His name is written ミカサ・アッカーマン in Japanese"],"options":["Sasha Blouse","Hange Zoë","Annie Leonhart","Mikasa Ackerman"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-mikasa-ackerman-name-032","attack-on-titan-hange-zoe-name-036","attack-on-titan-sasha-blouse-name-039","attack-on-titan-annie-leonhart-name-044"],"source_url":"https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters"},{"question":"Who is this?","clues":["Eren''s bookish childhood friend","Physically frail but a sharp strategist","Dreams of seeing the world beyond the walls"],"options":["Connie Springer","Armin Arlert","Marco Bott","Jean Kirstein"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-armin-arlert-name-033","attack-on-titan-jean-kirstein-name-037","attack-on-titan-connie-springer-name-038","attack-on-titan-marco-bott-name-