insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_07'), (select id from public.groups where slug = 'attack-on-titan' and site_id = 'anime'), 'Walls, Squads and Titans: Attack on Titan Odd One Out', 'walls-squads-and-titans-attack-on-titan-odd-one-out', 'intruder', '[{"question":"Three of these are the great walls that protect humanity. Which one is a city built inside one of them?","options":[{"label":"Wall Rose"},{"label":"Wall Sina"},{"label":"Wall Maria"},{"label":"Trost"}],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-wall-maria-first-073","attack-on-titan-wall-rose-second-074","attack-on-titan-wall-sina-inner-075","attack-on-titan-trost-city-076"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan"},{"question":"Three of these songs open episodes of the anime. Which one plays over the end credits instead?","options":[{"label":"Shinzo wo Sasageyo!"},{"label":"Great Escape"},{"label":"Guren no Yumiya"},{"label":"Jiyu no Tsubasa"}],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["attack-on-titan-opening-themes-008","attack-on-titan-ending-themes-009"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)"},{"question":"The army inside the Walls has three branches. Which of these is not one of them?","options":[{"label":"Garrison Regiment"},{"label":"Survey Corps"},{"label":"Training Corps"},{"label":"Military Police Brigade"}],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-military-divisions-061","attack-on-titan-training-corps-school-062"],"source_url":"https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters"},{"question":"Three of these are among the Nine Titans. Which one is not?","options":[{"label":"Smiling Titan"},{"label":"Female Titan"},{"label":"Colossal Titan"},{"label":"Armored Titan"}],"correct":0,"kind":"lore","spoiler":{"arc":1,"scope":"both"},"fact_ids":["attack-on-titan-nine-titans-list-091","attack-on-titan-smiling-titan-064"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan"},{"question":"Three of these officers lead a squad in the Survey Corps. Which one commands the Military Police instead?","options":[{"label":"Hange Zoë"},{"label":"Mike Zacharius"},{"label":"Levi Ackerman"},{"label":"Nile Dok"}],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-mike-squad-leader-069","attack-on-titan-hange-fourth-squad-070","attack-on-titan-levi-elite-squad-071","attack-on-titan-nile-dok-mp-072"],"source_url":"https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters"},{"question":"Three of these characters serve in the Garrison Regiment. Which one is a Survey Corps soldier?","options":[{"label":"Dot Pixis"},{"label":"Nanaba"},{"label":"Hannes"},{"label":"Rico Brzenska"}],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["attack-on-titan-hannes-garrison-065","attack-on-titan-rico-garrison-066","attack-on-titan-pixis-garrison-067","attack-on-titan-nanaba-survey-068"],"source_url":"https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters"},{"question":"Three of these were hand-picked for Captain Levi''s special squad. Which one works for Hange instead?","options":[{"label":"Moblit Berner"},{"label":"Petra Ral"},{"label":"Eld Jinn"},{"label":"Oluo Bozado"}],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["attack-on-titan-squad-levi-members-077","attack-on-titan-moblit-hange-aide-078"],"source_url":"https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters"},{"question":"Three of these cadets of the 104th Training Corps hid a Titan power. Which one did not?","options":[{"label":"Bertolt Hoover"},{"label":"Jean Kirstein"},{"label":"Reiner Braun"},{"label":"Annie Leon