insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'black-clover' and site_id = 'anime'), 'Black Clover Hard Quiz: Elves, Devils and the Secrets of the Wizard Kings', 'elves-devils-and-the-secrets-of-the-wizard-kings-black-clover-hard-quiz', 'multiple_choice', '[{"question":"Which elf shares his body with the captain of the Golden Dawn?","options":["Licht","Patry","Vetto","Fana"],"correct":1,"kind":"character","spoiler":{"arc":9,"scope":"both"},"fact_ids":["black-clover-william-patry-095"],"source_url":"https://en.wikipedia.org/wiki/List_of_Black_Clover_characters"},{"question":"Whose reincarnated unborn son is tied to Yuno''s four-leaf grimoire?","options":["The elf Licht","The first Wizard King Lumiere","The devil Zagred","The Silva heir Nozel"],"correct":0,"kind":"lore","spoiler":{"arc":10,"scope":"both"},"fact_ids":["black-clover-yuno-vessel-066"],"source_url":"https://en.wikipedia.org/wiki/List_of_Black_Clover_characters"},{"question":"How does Asta finally destroy the devil Zagred?","options":["By sealing him inside a grimoire","By cutting his heart in two","By drowning him in the sea","By burning him with Fire Magic"],"correct":1,"kind":"character","spoiler":{"arc":10,"scope":"both"},"fact_ids":["black-clover-zagred-end-102"],"source_url":"https://en.wikipedia.org/wiki/List_of_Black_Clover_characters"},{"question":"Which devil did Secre seal with her Sealing Magic?","options":["Zagred","Lucifero","Megicula","Liebe"],"correct":0,"kind":"lore","spoiler":{"arc":10,"scope":"both"},"fact_ids":["black-clover-secre-seal-087","black-clover-devils-025"],"source_url":"https://en.wikipedia.org/wiki/List_of_Black_Clover_characters"},{"question":"What is the hidden secret of the Wizard King Julius Novachrono?","options":["He is the reincarnated s