insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'black-clover' and site_id = 'anime'), 'Black Clover Quiz: Jump Magazines, Studio Pierrot and Tabata''s Habits', 'jump-magazines-studio-pierrot-and-tabatas-habits-black-clover-quiz', 'multiple_choice', '[{"question":"Who wrote and drew the Black Clover manga?","options":["Yūki Tabata","Eiichiro Oda","Tite Kubo","Hiro Mashima"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["black-clover-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Black_Clover"},{"question":"In which magazine did Black Clover start in February 2015?","options":["Weekly Shōnen Jump","Weekly Shōnen Magazine","Weekly Shōnen Sunday","Monthly Shōnen Sirius"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["black-clover-manga-run-003","black-clover-magazine-004"],"source_url":"https://en.wikipedia.org/wiki/Black_Clover"},{"question":"Which magazine carried the manga for its final years?","options":["Jump Square","Saikyō Jump","Shōnen Jump+","Jump Giga"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["black-clover-magazine-004"],"source_url":"https://en.wikipedia.org/wiki/Black_Clover"},{"question":"Which studio animates the TV anime?","options":["MAPPA","Wit Studio","Bones","Studio Pierrot"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["black-clover-studio-009"],"source_url":"https://en.wikipedia.org/wiki/Black_Clover_(TV_series)"},{"question":"How many episodes did the first TV season run?","options":["170","94","125","220"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["black-clover-anime-s1-007"],"source_url":"https://en.wikipedia.org/wiki/Black_Clover_(TV_series)"