insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_13'), (select id from public.groups where slug = 'dandadan' and site_id = 'anime'), 'Psychics, Yōkai and Aliens: Who Is Who?', 'psychics-yokai-and-aliens-who-is-who', 'multiple_choice', '[{"question":"Who is the grandmother of Momo and a spirit medium?","options":["Aira Shiratori","Seiko Ayase","Turbo Granny","Peeny-Weeny"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-seiko-spirit-medium-019"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which character is the psychic high-school girl?","options":["Aira Shiratori","Momo Ayase","Seiko Ayase","Turbo Granny"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-momo-ayase-name-021","dandadan-turbo-granny-name-023","dandadan-seiko-ayase-name-024","dandadan-aira-shiratori-name-025"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which occult-obsessed boy goes by the nickname Okarun?","options":["Ken Takakura","Jin Enjoji","Aira Shiratori","Momo Ayase"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-momo-ayase-name-021","dandadan-ken-takakura-name-022","dandadan-aira-shiratori-name-025","dandadan-jin-enjoji-name-028"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which of these characters is an antagonist of Dandadan?","options":["Seiko Ayase","Aira Shiratori","Jin Enjoji","Alien Serpo"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-alien-serpo-name-027","dandadan-seiko-ayase-name-024","dandadan-aira-shiratori-name-025","dandadan-jin-enjoji-name-028"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_chara