insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_13'), (select id from public.groups where slug = 'dandadan' and site_id = 'anime'), 'Two Seasons and Beyond: The Dandadan Timeline', 'two-seasons-and-beyond-the-dandadan-timeline', 'multiple_choice', '[{"question":"How many episodes did season two run for?","options":["12","10","24","26"],"correct":0,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["dandadan-anime-season-two-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_episodes"},{"question":"On which date did season two begin?","options":["October 3, 2024","January 11, 2025","July 3, 2025","April 6, 2021"],"correct":2,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["dandadan-anime-season-two-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_episodes"},{"question":"Only one of these characters is a supporting character, not an antagonist. Which one?","options":["Evil Eye","Reiko Kashima","Count Saint-Germain","Rin Sawaki"],"correct":3,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["dandadan-rin-sawaki-name-032","dandadan-evil-eye-name-030","dandadan-reiko-kashima-name-037","dandadan-count-saint-germain-name-038"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Season two again aired just after midnight. On which weekday?","options":["Thursday","Tuesday","Saturday","Sunday"],"correct":0,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["dandadan-anime-season-two-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_episodes"},{"question":"In which year is the premiere of the announced third season planned?","options":["2025","2027","2026","2028"],"correct":1,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["dandadan-sea