insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_13'), (select id from public.groups where slug = 'dandadan' and site_id = 'anime'), 'Voice, Habit, Hint: Dandadan in Three Clues', 'voice-habit-hint-dandadan-in-three-clues', 'guess_from_clues', '[{"question":"Who is this character?","clues":["In the Japanese version, she is voiced by Nana Mizuki.","She hosts a television show where she tells fortunes, and it has made her rich.","She looks about twenty, yet she is Momo''s grandmother."],"options":["Aira Shiratori","Momo Ayase","Turbo Granny","Seiko Ayase"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-seiko-voice-jp-041","dandadan-seiko-tv-fortune-042","dandadan-seiko-looks-twenty-068","dandadan-seiko-spirit-medium-019"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which yokai is this?","clues":["In Japanese, this yokai is voiced by Mayumi Tanaka.","Long ago, she was a gentle presence for the ghosts of girls who met a terrible end.","Seiko locks her spirit inside a lucky cat doll."],"options":["Turbo Granny","Aira Shiratori","Seiko Ayase","Alien Serpo"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-turbo-granny-voice-jp-044","dandadan-turbo-granny-comforter-069","dandadan-turbo-granny-doll-046"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which aliens are these?","clues":["Kazuya Nakai is their Japanese voice.","They come from a planet of their own and have no females at all.","They kidnap people from Earth to get body parts they lack."],"options":["Alien Serpo","Turbo Granny","Peeny-Weeny","Jin Enjoji"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-serpo-voice-jp-047","dandadan-serpo-all-male-race-048","dandadan-serpo-abductions-049"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Who is this character?","clues":["In Japanese, she is voiced by Ayane Sakura.","She is sure that heaven picked her to drive out yokai.","At Kami High, she is the idol of the school."],"options":["Aira Shiratori","Seiko Ayase","Momo Ayase","Turbo Granny"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-aira-voice-jp-050","dandadan-aira-chosen-exorcist-070","dandadan-aira-school-idol-052"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Who is this character?","clues":["Kaito Ishikawa is his Japanese voice.","He looks like a handsome athlete, but he is a goofy soul who praises everyone.","He is Momo''s childhood friend and ends up living with her and Seiko."],"options":["Alien Serpo","Peeny-Weeny","Jin Enjoji","Ken Takakura"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dandadan-jiji-voice-jp-053","dandadan-jiji-eccentric-jock-054","dandadan-jiji-moves-in-055"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which yokai is this?","clues":["His Japanese voice is Mutsumi Tamura.","Hot water calms him down, and cold brings his power back.","He was born from a human sacrifice and later bonds with a boy."],"options":["Turbo Granny","Alien Serpo","Acrobatic Silky","Evil Eye"],"correct":3,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["dandadan-evil-eye-voice-jp-056","dandadan-evil-eye-hot-cold-057","dandadan-evil-eye-human-sacrifice-058","dandadan-jiji-moves-in-055"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Who is this character?","clues":["Daichi Fujiwara is his Japanese voice.","He keeps hitting on girls, who reject him almost every time.","His love of aliens makes him the best user of nanoskin."],"options":["Jin Enjoji","Kinta Sakata","Ken Takakura","Peeny-Weeny"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["dandadan-kinta-voice-jp-059","dandadan-kinta-unwelcome-advances-060","dandadan-kinta-nanoskin-061"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Who is this character?","clues":["In Japanese, Tomokazu Sugita voices him.","He is a living anatomical model.","He lives at the high school of Momo and Okarun and is madly in love with Hana."],"options":["Chiquitita","Taro","Peeny-Weeny","Hana"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["dandadan-taro-voice-jp-062","dandadan-taro-anatomical-model-063","dandadan-taro-loves-hana-064"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Who is this character?","clues":["She is a strict class representative.","In private she is a secret fan of vampires.","Her gravity powers are tied to her singing."],"options":["Seiko Ayase","Aira Shiratori","Rin Sawaki","Momo Ayase"],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["dandadan-rin-class-rep-vampires-066","dandadan-rin-gravity-singing-067"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_characters"},{"question":"Which season is this?","clues":["Its ending song is Doukashiteru by WurtS.","Its opening song is Kakumei Dochu by Aina the End.","It began in July 2025."],"options":["Season 4","Season 2","Season 3","Season 1"],"correct":1,"kind":"production","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["dandadan-themes-season-two-014","dandadan-anime-season-two-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dandadan_episodes"}]'::jsonb, 'medium', 'published', 10, 'anime', 2, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_01'), (select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Shinigami, Wammy''s House and the Later Cast: Death Note', 'before-and-after-episode-26-death-note-by-part', 'multiple_choice', '[{"question":"Which of these characters is listed as a main character of Death Note?","options":["Teru Mikami","Sidoh","Near","Kiyomi Takada"],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-near-name-039","death-note-teru-mikami-name-038","death-note-sidoh-name-037","death-note-kiyomi-takada-name-036"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"What does the scrawny detective L do in his chair?","options":["He crouches in it","He sits up straight in it","He leans back in it","He spins around in it"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-l-habits-015"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which Shinigami delivers a Death Note to Misa Amane in the first half?","options":["Ryuk","Naomi Misora","Watari","Rem"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["death-note-ryuk-name-023","death-note-misa-amane-name-024","death-note-watari-name-032","death-note-rem-name-033","death-note-naomi-misora-name-035"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Who is Watari on the surface, an inventor who founded Wammy''s House?","options":["Soichiro Yagami","Quillsh Wammy","Teru Mikami","Raye Penber"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-watari-wammy-016"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"What kind of place is Wammy''s House?","options":["A police training academy","A home for gifted orphans","A hospital for detectives","A prison for criminals"],"correct":1,"kind":"lore","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-watari-wammy-016"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"What does Mello almost always carry?","options":["An apple","A notebook","A cup of tea","A chocolate bar"],"correct":3,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-mello-chocolate-017"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which two characters are the successors named in the second group of the cast?","options":["Near and Mello","Kiyomi Takada and Teru Mikami","Sidoh and Kiyomi Takada","Teru Mikami and Sidoh"],"correct":0,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-near-name-039","death-note-mello-name-040","death-note-teru-mikami-name-038","death-note-kiyomi-takada-name-036","death-note-sidoh-name-037"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which character is the Shinigami who sets out to get a stolen Death Note back?","options":["Rem","Ryuk","Sidoh","Watari"],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-ryuk-name-023","death-note-watari-name-032","death-note-rem-name-033","death-note-sidoh-name-037"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which character is the criminal prosecutor and fanatical worshipper of Kira whom Light picks as a new proxy?","options":["Kiyomi Takada","Near","Sidoh","Teru Mikami"],"correct":3,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-near-name-039","death-note-teru-mikami-name-038","death-note-kiyomi-takada-name-036","death-note-sidoh-name-037"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which character is Light''s classmate and girlfriend who returns years later as a TV announcer?","options":["Kiyomi Takada","Misa Amane","Sayu Yagami","Naomi Misora"],"correct":0,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["death-note-misa-amane-name-024","death-note-kiyomi-takada-name-036","death-note-sayu-yagami-name-027","death-note-naomi-misora-name-035"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"}]'::jsonb, 'hard', 'published', 10, 'anime', 2, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_01'), (select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Name and Face: Death Note True or False', 'name-and-face-death-note-true-or-false', 'true_false', '[{"question":"The Japanese title, Desu Nōto, is simply the English name spelled in katakana.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-japanese-title-001"],"source_url":"https://ja.wikipedia.org/wiki/DEATH_NOTE"},{"question":"Takeshi Obata writes the story and Tsugumi Ohba draws it.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-manga-creators-002"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"The manga appeared in Weekly Shōnen Jump between December 2003 and May 2006.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["death-note-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"The 108 weekly chapters were gathered into twenty tankōbon volumes.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["death-note-manga-size-004"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_chapters"},{"question":"Circulation passed thirty million copies by spring 2015.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["death-note-copies-in-print-012"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"The anime ran for 37 episodes on Nippon Television, from autumn 2006 to the summer of 2008.","correct":false,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-anime-run-006"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Ohba picked names that sound plausible yet are not found in real life.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-character-names-011"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"A victim dies as soon as the writer puts down the name, even without picturing the face.","correct":false,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-notebook-rule-013"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Ryuk, the Shinigami who loses his notebook, has a weakness for apples.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-ryuk-apples-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"An American film version premiered in cinemas in August 2017.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-netflix-film-019"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_01'), (select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Nightmare, Hormone and Madhouse: Death Note Behind the Screen', 'nightmare-hormone-and-madhouse-death-note-behind-the-screen', 'multiple_choice', '[{"question":"Which band performed the first opening of the Death Note anime?","options":["Maximum the Hormone","Yoshihisa Hirano","Nightmare","Aimer"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-theme-songs-010"],"source_url":"https://en.wikipedia.org/wiki/Death_Note_(2006_TV_series)"},{"question":"Which band took over both the opening and the ending slots in the second half?","options":["Maximum the Hormone","Nightmare","Yoshihisa Hirano","milet"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-theme-songs-010"],"source_url":"https://en.wikipedia.org/wiki/Death_Note_(2006_TV_series)"},{"question":"Who composed the short piece that ends the last episode?","options":["Nightmare","Maximum the Hormone","Aimer","Yoshihisa Hirano"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-theme-songs-010"],"source_url":"https://en.wikipedia.org/wiki/Death_Note_(2006_TV_series)"},{"question":"How many different opening songs does the Death Note anime use?","options":["1","2","3","5"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-theme-songs-010"],"source_url":"https://en.wikipedia.org/wiki/Death_Note_(2006_TV_series)"},{"question":"How many different ending songs does the Death Note anime use?","options":["2","3","4","5"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-theme-songs-010"],"source_url":"https://en.wikipedia.org/wiki/Death_Note_(2006_TV_series)"},{"question":"Which company serialized the Death Note story in Weekly Shōnen Jump?","options":["Kodansha","Shueisha","Shogakukan","Square Enix"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["death-note-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"On which broadcaster did the Death Note anime run?","options":["Nippon Television","Madhouse","Shueisha","Viz Media"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-anime-run-006"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"In which month and year did the Death Note anime begin?","options":["April 2006","June 2007","October 2006","October 2007"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["death-note-anime-run-006"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Who wrote the prose spin-off Another Note, published in 2006?","options":["Tsugumi Ohba","Takeshi Obata","Tetsurō Araki","Nisio Isin"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-another-note-018"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Which company holds the North American licence for the Death Note books and anime?","options":["Viz Media","Shueisha","Madhouse","Nippon Television"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-north-america-license-020"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_or