insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_01'), (select id from public.groups where slug = 'death-note' and site_id = 'anime'), 'Task Force Roll Call: Death Note Who Is Who', 'task-force-roll-call-death-note-who-is-who', 'multiple_choice', '[{"question":"Which character is the brilliant, bored high school student who finds a notebook that kills anyone whose name is written in it?","options":["Touta Matsuda","Shuichi Aizawa","Light Yagami","Hideki Ide"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-light-yagami-name-021","death-note-touta-matsuda-name-026","death-note-shuichi-aizawa-name-028","death-note-hideki-ide-name-030"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which character is the world-famous detective who takes on the hunt for the killer known as Kira?","options":["L","Soichiro Yagami","Raye Penber","Hirokazu Ukita"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["death-note-l-name-022","death-note-soichiro-yagami-name-025","death-note-hirokazu-ukita-name-031","death-note-raye-penber-name-034"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which character is the bored Shinigami who drops his Death Note into the human world?","options":["Light Yagami","L","Watari","Ryuk"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["death-note-light-yagami-name-021","death-note-l-name-022","death-note-ryuk-name-023","death-note-watari-name-032"],"source_url":"https://en.wikipedia.org/wiki/List_of_Death_Note_characters"},{"question":"Which character is the popular idol with a gothic style and a deep devotion to Light?","options":["Sayu Yagami","Misa Amane","Naomi Misora","Rem"],"correct":1,"kin