insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'detective-conan' and site_id = 'anime'), 'Detective Conan Quiz: A Shrunken Sleuth, Two Titles and a Town Named After Him', 'a-shrunken-sleuth-two-names-and-a-town-detective-conan-quiz', 'multiple_choice', '[{"question":"Who created the Detective Conan manga?","options":["Masashi Kishimoto","Gosho Aoyama","Tite Kubo","Eiichiro Oda"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["detective-conan-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed"},{"question":"The manga started in 1994 in which Shogakukan magazine?","options":["Weekly Shōnen Sunday","Monthly Shōnen Gangan","Weekly Shōnen Magazine","Weekly Shōnen Jump"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["detective-conan-magazine-003","detective-conan-manga-start-005"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed"},{"question":"Which pop singer has sung more theme songs for a single anime series than anyone else, according to Guinness?","options":["Hikaru Utada","Namie Amuro","Mai Kuraki","Ayumi Hamasaki"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["detective-conan-guinness-016"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed"},{"question":"In which year did the first Detective Conan film reach cinemas?","options":["1997","1996","1999","2001"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["detective-conan-first-film-013"],"source_url":"https://en.wikipedia.org/wiki/Case_Closed_(TV_series)"},{"question":"Why were several American releases renamed Case Closed?","options":["Because the show was merged with another","Because of legal problems with the original name","Because 