insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'dr-stone' and site_id = 'anime'), 'Dr. Stone Quiz: Petrified for 3,700 Years, Rebuilt with Science', 'petrified-for-3700-years-a-kingdom-of-science-dr-stone-quiz', 'multiple_choice', '[{"question":"Who draws the Dr. Stone manga, while Riichiro Inagaki writes the story?","options":["Boichi","Yusuke Murata","Sui Ishida","Takeshi Obata"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["dr-stone-creators-002"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"The story picks up roughly how long after the green flash petrifies humanity?","options":["About 37 years","About 3,700 years","About 37,000 years","About 370 years"],"correct":1,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dr-stone-setting-009"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"After hunting, Tsukasa wears the skin of which animal?","options":["A wolf","A tiger","A bear","A lion"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dr-stone-tsukasa-shishio-pelt-051"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Senku teases his best friend as a big oaf. Who is that friend?","options":["Kokuyo","Tsukasa Shishio","Chrome","Taiju Oki"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dr-stone-taiju-oki-name-047"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Which company licensed the Dr. Stone manga for North America?","options":["Seven Seas","Kodansha USA","Yen Press","Viz Media"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["dr-stone-viz-licence-019"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"Inagaki says the personality of Senku echoes which character of his earlier manga Eyeshield 21?","options":["Monta Mizumachi","Sena Kobayakawa","Agon Kongo","Yoichi Hiruma"],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["dr-stone-inspiration-010"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"Which prize did the manga win in 2019?","options":["Kodansha Manga Award","Shogakukan Manga Award","Tezuka Osamu Cultural Prize","Eisner Award"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["dr-stone-award-shogakukan-014"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"The season that aired from July to December 2019 was made of how many episodes?","options":["13","26","24","12"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dr-stone-season-1-026"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_episodes"},{"question":"Which band performed the first opening, Good Morning World!?","options":["Kana-Boon","Burnout Syndromes","Fujifabric","Pelican Fanclub"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dr-stone-themes-s1-039"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"What career does Yuzuriha dream of?","options":["Chef","Fashion designer","Pilot","Doctor"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dr-stone-yuzuriha-ogawa-name-049"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = exclud