insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'dr-stone' and site_id = 'anime'), 'Dr. Stone Hard Quiz: Platinum, a Second Wave and a Rocket to the Moon', 'platinum-a-second-wave-and-a-rocket-to-the-moon-dr-stone-hard-quiz', 'multiple_choice', '[{"question":"Byakuya left a stock of which metal on an island, to be used as a catalyst for the revival fluid?","options":["Copper","Platinum","Titanium","Gold"],"correct":1,"kind":"lore","spoiler":{"arc":4,"scope":"both"},"fact_ids":["dr-stone-platinum-075"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"Who is the only person still awake after the second worldwide petrification?","options":["Senku","Suika","Kohaku","Chelsea"],"correct":1,"kind":"character","spoiler":{"arc":5,"scope":"both"},"fact_ids":["dr-stone-suika-wave-077"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"},{"question":"Which former NASA scientist leads the colony in the United States?","options":["Dr. Volkov","Dr. Xeno","Dr. Ishigami","Dr. Nanami"],"correct":1,"kind":"character","spoiler":{"arc":5,"scope":"both"},"fact_ids":["dr-stone-dr-xeno-name-069"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is the second in command of the American colony?","options":["Joel Gear","Brody Dudley","Stanley Snyder","Carlos Barrios"],"correct":2,"kind":"character","spoiler":{"arc":5,"scope":"both"},"fact_ids":["dr-stone-stanley-snyder-name-070"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Which minister seizes power in the Petrification Kingdom and uses the Petrification Device on those who threaten him?","options":["Ibara","Matsukaze","Kirisame","Oarashi"],"correct":0,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["dr-stone-ibara-name-082"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Which barefoot villager with a photographic memory ends up leading the Petrification Kingdom?","options":["Magma","Soyuz","Amaryllis","Moz"],"correct":1,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["dr-stone-soyuz-name-083"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"What turns out to be hidden behind the name Why-Man?","options":["A secret army of the Tsukasa Empire","The shared consciousness of the petrification devices","A rival scientist on the Moon","An artificial intelligence made by NASA"],"correct":1,"kind":"lore","spoiler":{"arc":5,"scope":"both"},"fact_ids":["dr-stone-why-man-nature-078"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Which name is given to whoever petrifies humanity from the surface of the Moon?","options":["Why-Man","Moon-Man","Stone-Man","Who-Man"],"correct":0,"kind":"lore","spoiler":{"arc":5,"scope":"both"},"fact_ids":["dr-stone-why-man-name-072"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"What is the title of the very last episode of the anime?","options":["Giant Step","Ushers of an Exhilarating Future","Beyond the New World","Prologue of Dr. Stone"],"correct":1,"kind":"episode","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["dr-stone-last-episodes-074"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_episodes"},{"question":"Which three chapter spin-off, set after the main finale, ran in late 2023?","options":["Dr. Stone: Ryusui","Dr. Stone: 4D Science","Dr. Stone: Terraforming","Dr. Stone: Reboot Byakuya"],"correct":1,"kind":"manga","spoiler":{"arc":5,"scope":"manga"},"fact_ids":["dr-stone-spinoff-4d-035"],"source_url":"https://en.wikipedia.org/wiki/Dr._Stone"}]'::jsonb, 'hard', 'published', 10, 'anime', 5, 'manga') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'dr-stone' and site_id = 'anime'), 'Who Is This? Dr. Stone Characters in Three Clues', 'who-is-this-dr-stone-character-in-three-clues', 'guess_from_clues', '[{"question":"Who is this character?","clues":["Yūsuke Kobayashi gives this person a voice in Japanese.","Astronomy and space travel are the favorite fields.","This teenager fakes a death to throw off a hunter."],"options":["Chrome","Senku Ishigami","Taiju Oki","Gen Asagiri"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-senku-ishigami-name-044","dr-stone-senku-ishigami-voice-046","dr-stone-senku-ishigami-interest-045","dr-stone-senku-ishigami-fake-death-080"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["This person is a pacifist who has never thrown a punch.","Stamina and strength seem to have no limit.","The heart belongs to a girl from the handicrafts club."],"options":["Kokuyo","Taiju Oki","Senku Ishigami","Tsukasa Shishio"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dr-stone-taiju-oki-strength-084","dr-stone-taiju-oki-love-085","dr-stone-taiju-oki-name-047","dr-stone-yuzuriha-ogawa-name-049"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["A talent for sewing and working with cloth.","The dream is a career in fashion.","The best friend of Senku is in love with this person."],"options":["Ruri","Yuzuriha Ogawa","Kohaku","Suika"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-yuzuriha-ogawa-name-049","dr-stone-yuzuriha-ogawa-talent-086","dr-stone-taiju-oki-love-085"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["This martial arts star has a nickname about a primate.","The belief is that strength should rule the new world.","A big cat pelt hangs over the shoulders."],"options":["Kokuyo","Tsukasa Shishio","Taiju Oki","Gen Asagiri"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-tsukasa-shishio-name-050","dr-stone-tsukasa-shishio-motive-079","dr-stone-tsukasa-shishio-pelt-051","dr-stone-tsukasa-shishio-voice-052"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["This warrior is the first villager that Senku meets.","A running joke compares this person to a gorilla.","An older sister is the priestess of the village."],"options":["Yuzuriha Ogawa","Kohaku","Suika","Ruri"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-kohaku-name-053","dr-stone-kohaku-gag-087","dr-stone-kohaku-sister-088"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["This boy mistakes science for sorcery.","Collecting rocks is a hobby.","Later he becomes the partner of the genius from the old world."],"options":["Taiju Oki","Chrome","Kaseki","Kokuyo"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-chrome-name-054","dr-stone-chrome-hobby-055","dr-stone-chrome-partner-092"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["A young girl who keeps a fruit on her head.","Her helmet gets lenses made to measure.","She often goes scouting for Senku."],"options":["Kohaku","Suika","Yuzuriha Ogawa","Ruri"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-suika-name-056","dr-stone-suika-lenses-089"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["A silver-tongued man from the old world who calls himself a mentalist.","He walks barefoot in a yukata.","Revived by an enemy to check a death, he ends up switching sides."],"options":["Kaseki","Gen Asagiri","Chrome","Kokuyo"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-gen-asagiri-name-057","dr-stone-gen-asagiri-defect-081","dr-stone-gen-asagiri-voice-058"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["This elderly man is far stronger than he looks.","He shaped much of the village by hand.","Glass, engines and vacuum tubes come out of his workshop."],"options":["Chrome","Kaseki","Kokuyo","Gen Asagiri"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-kaseki-name-065","dr-stone-kaseki-craft-090"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"},{"question":"Who is this character?","clues":["This person is the high priestess of a village.","The Hundred Stories are in this keeper''s care.","An illness sets the first goal of the Kingdom of Science."],"options":["Suika","Ruri","Kohaku","Yuzuriha Ogawa"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["dr-stone-ruri-name-066","dr-stone-ruri-stories-091"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dr._Stone_characters"}]'::jsonb, 'medium', 'published', 10, 'anime', 1, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_08'), (select id from public.groups where slug = 'dragon-ball' and site_id = 'anime'), 'Dragon Ball Basics: Toriyama, Toei and the Monkey King', 'dragon-ball-basics-toriyama-toei-and-the-monkey-king', 'multiple_choice', '[{"question":"Who created the Dragon Ball franchise and wrote and drew the original manga on his own?","options":["Eiichiro Oda","Akira Toriyama","Masashi Kishimoto","Yoshihiro Togashi"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-series-creator-012"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"},{"question":"On which television network did the first Dragon Ball anime air?","options":["TV Tokyo","NHK","Fuji Television","TV Asahi"],"correct":2,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-dragon-ball-tv-run-016"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_(TV_series)"},{"question":"In which year did Dragon Ball Z end its run?","options":["1996","1989","1993","1999"],"correct":0,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-z-tv-run-017"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Z"},{"question":"Which studio produced the Dragon Ball anime television series?","options":["Studio Pierrot","Madhouse","Sunrise","Toei Animation"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-animation-studio-020"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Z"},{"question":"Which Chinese novel inspired the Dragon Ball story?","options":["Romance of the Three Kingdoms","Journey to the West","Water Margin","Dream of the Red Chamber"],"correct":1,"fun_fact":"Hong Kong kung fu films were mixed in.","kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-journey-to-the-west-023"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"},{"question":"Goku''s Japanese name, Son Goku, is how the Monkey King of Journey to the West is read. What is that Chinese name?","options":["Zhu Bajie","Sun Wukong","Sha Wujing","Tang Sanzang"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-goku-sun-wukong-024"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"},{"question":"How many episodes does the first Dragon Ball anime have?","options":["108","153","291","131"],"correct":1,"fun_fact":"It ran from February 1986 to April 1989 on Fuji Television.","kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-dragon-ball-tv-run-016"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_(TV_series)"},{"question":"How many episodes did Dragon Ball Z air?","options":["291","153","131","195"],"correct":0,"fun_fact":"Dragon Ball Z started in April 1989 and ended in January 1996.","kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-z-tv-run-017"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Z"},{"question":"Dragon Ball Super returned to television in July of which year, after a long gap?","options":["2009","2012","2018","2015"],"correct":3,"fun_fact":"It ran for 131 episodes.","kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-super-tv-run-018"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Super_(TV_series)"},{"question":"In which year did the original Dragon Ball manga begin in Weekly Shonen Jump?","options":["1979","1986","1984","1989"],"correct":2,"fun_fact":"It ran for a little over ten years, until May 1995.","kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["dragon-ball-manga-run-013"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excl