insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_08'), (select id from public.groups where slug = 'dragon-ball' and site_id = 'anime'), 'Dragon Ball True or False: Senzu Edition', 'dragon-ball-true-or-false-senzu-edition', 'true_false', '[{"question":"Akira Toriyama created the franchise and wrote and drew the original manga on his own.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-series-creator-012"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"},{"question":"The original Dragon Ball manga ran for a little over ten years in Weekly Shonen Jump, starting in November 1984.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["dragon-ball-manga-run-013"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"},{"question":"The franchise is called ドラゴンボール in Japan, read Dorakon Bōru.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-japanese-title-011"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_(TV_series)"},{"question":"The first Dragon Ball anime ran for 153 episodes on Fuji Television.","correct":true,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-dragon-ball-tv-run-016"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_(TV_series)"},{"question":"Dragon Ball Z aired 153 episodes before ending in January 1996.","correct":false,"fun_fact":"Dragon Ball Z aired 291 episodes.","kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-z-tv-run-017"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Z"},{"question":"Toei Animation produced the anime television series of the Dragon Ball franchise.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-animation-studio-020"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Z"},{"question":"Dragon Ball Super returned to television in July 2010.","correct":false,"fun_fact":"It returned in July 2015.","kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-super-tv-run-018"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Super_(TV_series)"},{"question":"The Dragon Ball story was inspired by the Chinese novel Journey to the West, with Hong Kong kung fu films mixed in.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-journey-to-the-west-023"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"},{"question":"Daima aired its 20 episodes between October 2024 and February 2025.","correct":true,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["dragon-ball-daima-tv-run-019"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball_Daima"},{"question":"Goku''s Japanese name, Son Goku, is how the Monkey King Sun Wukong of Journey to the West is read in Japanese.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-goku-sun-wukong-024"],"source_url":"https://en.wikipedia.org/wiki/Dragon_Ball"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_08'), (select id from public.groups where slug = 'dragon-ball' and site_id = 'anime'), 'Which One Does Not Belong? Dragon Ball Odd One Out', 'which-one-does-not-belong-dragon-ball-odd-one-out', 'intruder', '[{"question":"Three of these belong to the crew of Emperor Pilaf. Which one does not?","options":[{"label":"Oolong"},{"label":"Shu"},{"label":"Mai"},{"label":"Pilaf"}],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-pilaf-leads-gang-061","dragon-ball-shu-mai-gang-062","dragon-ball-oolong-wish-pig-063"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters"},{"question":"Three of these are anime series set in the Dragon Ball story. Which one is an earlier, separate manga by the same author?","options":[{"label":"Dragon Ball Z"},{"label":"Dragon Ball Super"},{"label":"Dragon Ball GT"},{"label":"Dr. Slump"}],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["dragon-ball-dr-slump-universe-064","dragon-ball-gt-sequel-series-065","dragon-ball-z-tv-run-017","dragon-ball-super-tv-run-018"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters"},{"question":"Three of these fighters learned martial arts from Master Roshi. Which one was trained by Roshi''s rival instead?","options":[{"label":"Goku"},{"label":"Yamcha"},{"label":"Tien Shinhan"},{"label":"Krillin"}],"correct":2,"kind":"character","spoiler":{"arc":7,"scope":"both"},"fact_ids":["dragon-ball-krillin-roshi-pupil-066","dragon-ball-yamcha-roshi-pupil-067","dragon-ball-tien-master-shen-068"],"source_url":"https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters"},{"question":"Three of these characters have names built on vegetable jokes. Which one is named after underwear?","optio