insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'From Episode 26 to Rebuild: Evangelion Odds and Ends', 'from-episode-26-to-rebuild-evangelion-odds-and-ends', 'multiple_choice', '[{"question":"Readers of which magazine voted the 1995 series top Best Loved Series at the Anime Grand Prix?","options":["Newtype","Nakayoshi","Weekly Shōnen Jump","Animage"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-animage-grand-prix-011"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"In which two years did the 1995 series place first as Best Loved Series?","options":["1995 and 1996","1996 and 1997","1997 and 1998","1996 and 1998"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-animage-grand-prix-011"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"In which year did Hideaki Anno begin shaping the project?","options":["1989","1993","1995","1997"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-production-start-010"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"On which date did the final episode of the 1995 series air?","options":["October 4, 1995","July 19, 1997","June 21, 2019","March 27, 1996"],"correct":3,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"The End of Evangelion is a new take on which part of the 1995 series?","options":["The last two episodes","The first two episodes","The middle episodes","Every episode"],"correct":0,"kind":"arc","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"In which Rebuild film does Mari first appear?","options":["The first","The third","The second","The fourth"],"correct":2,"kind":"character","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-mari-debut-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"In which year did that Rebuild film come out?","options":["2007","2012","2021","2009"],"correct":3,"kind":"character","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-mari-debut-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"In which year was the last Rebuild film shown?","options":["2021","2007","2009","2012"],"correct":0,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-rebuild-films-009"],"source_url":"https://en.wikipedia.org/wiki/Rebuild_of_Evangelion"}]'::jsonb, 'hard', 'published', 8, 'anime', 5, 'anime') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'Gainax, Khara and Netflix: Evangelion Behind the Screens', 'gainax-khara-and-netflix-evangelion-behind-the-screens', 'multiple_choice', '[{"question":"Who co-directed The End of Evangelion with Hideaki Anno?","options":["Hayao Miyazaki","Kazuya Tsurumaki","Satoshi Kon","Mamoru Oshii"],"correct":1,"kind":"production","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"Which studio made The End of Evangelion together with Gainax?","options":["Madhouse","Production I.G","Bones","Studio Khara"],"correct":1,"kind":"production","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"On which date did The End of Evangelion reach Japanese cinemas?","options":["October 4, 1995","March 27, 1996","June 21, 2019","July 19, 1997"],"correct":3,"kind":"production","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"Which studio made the Rebuild of Evangelion films?","options":["Studio Khara","Gainax","Tatsunoko Production","Production I.G"],"correct":0,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-rebuild-films-009"],"source_url":"https://en.wikipedia.org/wiki/Rebuild_of_Evangelion"},{"question":"How many Rebuild of Evangelion films are there?","options":["Two","Three","Four","Six"],"correct":2,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-rebuild-films-009"],"source_url":"https://en.wikipedia.org/wiki/Rebuild_of_Evangelion"},{"question":"On which date was the first Rebuild film shown?","options":["19 July 1997","8 March 2021","21 June 2019","1 September 2007"],"correct":3,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008","evangelion-rebuild-films-009","evangelion-netflix-premiere-012"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"On which date was the last Rebuild film shown?","options":["8 March 2021","1 September 2007","19 July 1997","21 June 2019"],"correct":0,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008","evangelion-rebuild-films-009","evangelion-netflix-premiere-012"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"From which date did Netflix bring the 1995 series to a global audience?","options":["September 1, 2007","June 21, 2019","July 19, 1997","March 8, 2021"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-netflix-premiere-012"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Why is the closing song Fly Me to the Moon left out of the Netflix release outside Japan?","options":["Age rating rules","Running time limits","Licensing reasons","Dubbing costs"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-netflix-premiere-012"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Which prize did the opening A Cruel Angel''s Thesis take from Animage in 1996?","options":["Best opening animation","Best voice actor","Best song","Best director"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-opening-cruel-angel-005"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"}]'::jsonb, 'medium', 'published', 10, 'anime', 5, 'anime') on con