insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'Pilots, Nerv and Family: Who Is Who?', 'pilots-nerv-and-family-evangelion-who-is-who', 'multiple_choice', '[{"question":"Which withdrawn teenager pilots Unit 01?","options":["Shinji Ikari","Toji Suzuhara","Kozo Fuyutsuki","Ritsuko Akagi"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-shinji-ikari-name-016","evangelion-ritsuko-akagi-name-021","evangelion-toji-suzuhara-name-024","evangelion-kozo-fuyutsuki-name-025"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"Who is the quiet pilot of Unit 00?","options":["Asuka Langley Soryu","Misato Katsuragi","Ritsuko Akagi","Rei Ayanami"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-rei-ayanami-name-017","evangelion-asuka-langley-soryu-name-018","evangelion-misato-katsuragi-name-019","evangelion-ritsuko-akagi-name-021"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"Who is the fiery pilot of Unit 02?","options":["Rei Ayanami","Asuka Langley Soryu","Misato Katsuragi","Ritsuko Akagi"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-rei-ayanami-name-017","evangelion-asuka-langley-soryu-name-018","evangelion-misato-katsuragi-name-019","evangelion-ritsuko-akagi-name-021"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"Which Nerv captain becomes Shinji''s guardian?","options":["Ritsuko Akagi","Misato Katsuragi","Yui Ikari","Rei Ayanami"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["evangelion-rei-a