insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'Tokyo-3, 2015: Evangelion Basics', 'tokyo-3-2015-evangelion-basics', 'multiple_choice', '[{"question":"Which studio animated the 1995 series together with Tatsunoko Production?","options":["Sunrise","Madhouse","Gainax","Bones"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-studio-director-002"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Who directed the 1995 series?","options":["Hideaki Anno","Hayao Miyazaki","Satoshi Kon","Mamoru Oshii"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-studio-director-002"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Which channel aired the 1995 series in Japan?","options":["TV Asahi","Fuji TV","NHK","TV Tokyo"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"How many episodes does the single season of the 1995 series have?","options":["13","26","24","52"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"In which month of 1995 did the series start airing?","options":["January","October","April","July"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"In which year is the 1995 series set?","options":["1995","2000","2035","2015"],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-setting-tokyo-3-004"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"How many years before the story did a catastrophe hit the planet?","options":["15","5","10","30"],"correct":0,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-setting-tokyo-3-004"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Who sings the opening theme, A Cruel Angel''s Thesis?","options":["Claire Littley","Hiroko Moriguchi","Yoko Takahashi","Mai Yamane"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-opening-cruel-angel-005"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"Which British singer takes the lead on the closing song Fly Me to the Moon?","options":["Yoko Takahashi","Hiroko Moriguchi","Mai Yamane","Claire Littley"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["evangelion-ending-fly-me-006"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"},{"question":"What was Rei nicknamed after books with her on the cover sold so well?","options":["Premium Girl","Cover Girl","Best Girl","Lucky Girl"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-rei-premium-girl-015"],"source_url":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'Which Came First? Evangelion Angels, Episodes and Films', 'which-came-first-evangelion-angels-episodes-and-films', 'multiple_choice', '[{"question":"Angels are numbered in the TV series. Which of these four has the lowest number?","options":["Israfel","Gaghiel","Shamshel","Sachiel"],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-sachiel-number-3-029","evangelion-shamshel-number-4-030","evangelion-gaghiel-number-6-032","evangelion-israfel-number-7-033"],"source_url":"https://en.wikipedia.org/wiki/Angels_(Neon_Genesis_Evangelion)"},{"question":"Looking at Evangelion''s release history, which of these four milestones comes earliest?","options":["The Netflix worldwide premiere","The End of Evangelion","The TV season finishing on TV Tokyo","The first Rebuild film"],"correct":2,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003","evangelion-end-of-evangelion-film-008","evangelion-rebuild-films-009","evangelion-netflix-premiere-012","evangelion-rebuild-first-film-015"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"Among these Angels of the TV series, which one has the smallest number?","options":["Matarael","Israfel","Sandalphon","Ramiel"],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["evangelion-ramiel-number-5-031","evangelion-israfel-number-7-033","evangelion-sandalphon-number-8-034","evangelion-matarael-number-9-035"],"source_url":"https://en.wikipedia.org/wiki/Angels_(Neon_Genesis_Evangelion)"},{"question":"On the road from the TV series to the films, which of these steps happened first?","options":["The first Rebuild film opens","The End of Evangelion reaches cinemas","The TV season starting on TV Tokyo","The TV season finishing on TV Tokyo"],"correct":2,"kind":"production","spoiler":{"arc":5,"scope":"both"},"fact_ids":["evangelion-broadcast-run-003","evangelion-end-of-evangelion-film-008","evangelion-rebuild-films-009","evangelion-rebuild-first-film-015"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"The alternate ending came to cinemas in several steps. Which release came first?","options":["Death & Rebirth","The first Rebuild film","Revival of Evangelion","The End of Evangelion"],"correct":0,"kind":"production","spoiler":{"arc":5,"scope":"both"},"fact_ids":["evangelion-film-release-order-028","evangelion-rebuild-films-009","evangelion-rebuild-first-film-015"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"Four episodes of the TV series are described below. Which one comes first?","options":["The episode with Eva-01''s rampage","The episode where Anno digs into Rei","The episode that turns the show inward","The episode voted best-loved by fans"],"correct":1,"kind":"lore","spoiler":{"arc":2,"scope":"both"},"fact_ids":["evangelion-episode-14-rei-focus-044","evangelion-episode-16-inward-turn-045","evangelion-episode-18-rampage-046","evangelion-episode-24-best-loved-047"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"Among these later Angels, which one is numbered lowest?","options":["Zeruel","Sahaquiel","Arael","Ireul"],"correct":1,"kind":"lore","spoiler":{"arc":2,"scope":"both"},"fact_ids":["evangelion-sahaquiel-number-10-036","evangelion-ireul-number-11-037","evangelion-zeruel-number-14-038","evangelion-arael-number-15-039"],"source_url":"https://en.wikipedia.org/wiki/Angels_(Neon_Genesis_Evangelion)"},{"question":"Pilots carry numbered titles such as First Child. Which of these pilots has the lowest number?","options":["Asuka Langley Soryu","Shinji Ikari","Kaworu Nagisa","Toji Suzuhara"],"correct":0,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["evangelion-asuka-second-child-040","evangelion-shinji-third-child-041","evangelion-toji-fourth-child-042","evangelion-kaworu-fifth-child-043"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_characters"},{"question":"Four milestones are listed. Which is the most recent one?","options":["The End of Evangelion","The second Rebuild film, where Mari debuts","The TV season finishing on TV Tokyo","The first Rebuild film"],"correct":1,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-broadcast-run-003","evangelion-end-of-evangelion-film-008","evangelion-rebuild-films-009","evangelion-mari-debut-014","evangelion-rebuild-first-film-015"],"source_url":"https://en.wikipedia.org/wiki/List_of_Neon_Genesis_Evangelion_episodes"},{"question":"Now four other milestones: which of them is the latest of all?","options":["The last Rebuild film","The second Rebuild film, where Mari debuts","The Netflix worldwide premiere","The End of Evangelion"],"correct":0,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008","evangelion-mari-debut-014","evangelion-netflix-premiere-012","evangelion-rebuild-films-009"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"}]'::jsonb, 'medium', 'published', 10, 'anime', 5, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'fairy-tail' and site_id = 'anime'), 'Fairy Tail Hard Quiz: Black Wizards, Dragon Kings and the Final War', 'black-wizards-dragon-kings-and-the-final-war-fairy-tail-hard-quiz', 'multiple_choice', '[{"question":"Which demon identity does Natsu turn out to hold?","options":["Etherious Natsu Dragneel","Spriggan","Dragon King","Fairy Strategist"],"correct":0,"kind":"character","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-endpoint-065"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"How is Zeref related to Natsu?","options":["He is Natsu''s adoptive father","He is Natsu''s childhood teacher","He is Natsu''s older brother","He is Natsu''s younger cousin"],"correct":2,"kind":"character","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-zeref-brother-103"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"For how long did the Fairy Sphere hold the guild in suspended animation?","options":["One year","Three years","Twelve years","Seven years"],"correct":3,"kind":"lore","spoiler":{"arc":10,"scope":"both"},"fact_ids":["fairy-tail-mavis-sphere-100"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Which dragon kills Igneel in front of Natsu?","options":["Grandeeney","Acnologia","Metalicana","Weisslogia"],"correct":1,"kind":"character","spoiler":{"arc":15,"scope":"both"},"fact_ids":["fairy-tail-igneel-sealed-066","fairy-tail-acnologia-igneel-106"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Under the alias Spriggan, which military nation does Zeref rule?","options":["Grimoire Heart","Phantom Lord","The Alvarez Empire","The Magic Council"],"correct":2,"kind":"lore","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-zeref-alias-104"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"How did the curse shared by Mavis and Zeref finally end?","options":["Mavis accepted that love, and the curse ended both lives","Natsu burned the cursed book of Zeref","Acnologia swallowed the curse in a rift","Lucy broke the curse with a golden key"],"correct":0,"kind":"lore","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-mavis-zeref-101"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who gives up his life with the spell Fairy Law against the Alvarez army, before Mavis revives him?","options":["Gildarts Clive","Makarov Dreyar","Laxus Dreyar","Gajeel Redfox"],"correct":1,"kind":"character","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-makarov-death-109"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"What was Acnologia before he turned into a black dragon?","options":["A celestial spirit","An Exceed from Edolas","A human Dragon Slayer","A guild master"],"correct":2,"kind":"character","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-acnologia-human-105"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"How does Natsu finally destroy Acnologia?","options":["He sealed the dragon inside a crystal","He fed the dragon to the Eclipse gate","He dueled the dragon with a zodiac key","He gathered the magic of the other Dragon Slayers and destroyed the spirit"],"correct":3,"kind":"character","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-acnologia-end-107"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"What does Lucy publish at the end of the series?","options":["A novel based on her time at the guild","A spell book of the zodiac keys","A map of the whole kingdom","A history of the Magic Council"],"correct":0,"kind":"character","spoiler":{"arc":17,"scope":"both"},"fact_ids":["fairy-tail-lucy-novel-068"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"}]'::jsonb, 'hard', 'published', 10, 'anime', 17, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'fairy-tail' and site_id = 'anime'), 'Fairy Tail Wizards in Three Clues: Who Is This?', 'fairy-tail-wizards-in-three-clues-who-is-this', 'guess_from_clues', '[{"question":"Who is this wizard?","clues":["The nickname comes from the fairy queen of a Shakespeare play.","Weapons and armor are swapped in an instant with magic named The Knight.","Jellal named this swordswoman after the color of her hair."],"options":["Erza Scarlet","Mirajane Strauss","Lucy Heartfilia","Cana Alberona"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-erza-titania-073","fairy-tail-erza-requip-074","fairy-tail-character-name-048"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["He learned his magic from a teacher named Ur.","He forms weapons and objects out of ice.","He strips off his clothes without noticing."],"options":["Natsu Dragneel","Elfman Strauss","Gray Fullbuster","Makarov Dreyar"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-character-name-047","fairy-tail-gray-icemake-071","fairy-tail-gray-strip-072"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["Younger siblings named Lisanna and Elfman look up to this wizard.","The guild bar is run by this wizard, who also poses for a magazine.","Satan Soul lets this wizard take demon forms."],"options":["Cana Alberona","Levy McGarden","Mirajane Strauss","Lucy Heartfilia"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-character-name-050","fairy-tail-mirajane-model-078","fairy-tail-mirajane-soul-077"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["This old master sits among the Ten Wizard Saints.","Mashima wanted this name to sound Russian.","Magic named Giant makes this small man tower over everyone."],"options":["Elfman Strauss","Makarov Dreyar","Natsu Dragneel","Happy"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-makarov-saints-075","fairy-tail-character-name-049","fairy-tail-makarov-giant-076"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this?","clues":["This cat hatched from an egg that Natsu found.","Aera magic grows wings on this cat.","Natsu is never sick when he flies with this cat."],"options":["Carla","Happy","Loke","Makarov Dreyar"],"correct":1,"kind":"character","spoiler":{"arc":8,"scope":"both"},"fact_ids":["fairy-tail-character-name-046","fairy-tail-happy-aera-069"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["This wizard is part of the three person team Shadow Gear.","Written words become solid objects at this wizard''s command.","This wizard can read ancient runic languages."],"options":["Cana Alberona","Mirajane Strauss","Levy McGarden","Lucy Heartfilia"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-levy-team-083","fairy-tail-levy-script-082","fairy-tail-character-name-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["This wizard is the guild''s biggest drinker.","The name comes from a tarot word.","Magic cards serve as both weapons and fortune telling tools."],"options":["Levy McGarden","Mirajane Strauss","Lucy Heartfilia","Cana Alberona"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-cana-cards-080","fairy-tail-character-name-052"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["The nickname Kurogane was given to this wizard in a rival guild.","This wizard eats iron to get stronger.","Iron Dragon Slayer Magic is the power of this wizard."],"options":["Gajeel Redfox","Natsu Dragneel","Laxus Dreyar","Gray Fullbuster"],"correct":0,"kind":"character","spoiler":{"arc":6,"scope":"both"},"fact_ids":["fairy-tail-gajeel-nick-087","fairy-tail-gajeel-iron-086"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["The streets of Magnolia rearrange to guide this wizard home.","Anything this wizard touches breaks into blocks.","The guild considers this S-Class wizard its strongest member."],"options":["Laxus Dreyar","Makarov Dreyar","Gajeel Redfox","Gildarts Clive"],"correct":3,"kind":"character","spoiler":{"arc":9,"scope":"both"},"fact_ids":["fairy-tail-gildarts-streets-097","fairy-tail-gildarts-crush-096","fairy-tail-character-name-060"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Who is this wizard?","clues":["The name comes from the Japanese word for Wednesday.","Mashima made this wizard twelve years old after a staff comment.","Healing magic from clean air is the specialty of this Sky Dragon Slayer."],"options":["Lucy Heartfilia","Wendy Marvell","Carla","Cana Alberona"],"correct":1,"kind":"character","spoiler":{"arc":8,"scope":"both"},"fact_ids":["fairy-tail-character-name-058","fairy-tail-wendy-design-094","fairy-tail-wendy-sky-093"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"}]'::jsonb, 'medium', 'published', 10, 'anime', 9, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'fairy-tail' and site_id = 'anime'), 'Fairy Tail Quiz: Mashima''s Guild, TV Tokyo and 328 Episodes', 'mashimas-guild-tv-tokyo-and-328-episodes-fairy-tail-quiz', 'multiple_choice', '[{"question":"Which magazine ran the Fairy Tail manga every week?","options":["Weekly Shōnen Jump","Weekly Shōnen Magazine","Weekly Shōnen Sunday","Monthly Shōnen Sirius"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fairy-tail-magazine-003"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail"},{"question":"How many tankōbon volumes did the manga fill by the end of its run?","options":["42","54","88","63"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fairy-tail-volumes-005"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail"},{"question":"In which year did the first Fairy Tail TV episode air on TV Tokyo?","options":["2009","2006","2011","2014"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-anime-s1-009"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_episodes"},{"question":"Across all seasons, how many episodes does the TV anime have?","options":["175","263","328","412"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-anime-total-012"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail_(TV_series)"},{"question":"Which pair of studios animated the first TV season?","options":["Bones and Madhouse","MAPPA and Wit Studio","A-1 Pictures and Satelight","Pierrot and Sunrise"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-anime-studios-013"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_episodes"},{"question":"What was the title of the one-shot that Mashima used as a pilot before the series?","options":["Rave Master","Fairy Tale","Monster Hunter Orage","Fairy Tail Zero"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["fairy-tail-pilot-006"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail"},{"question":"Natsu''s name is the Japanese word for which season?","options":["Spring","Autumn","Summer","Winter"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fairy-tail-natsu-name-032"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail"},{"question":"Who composed and arranged the music for the Fairy Tail anime?","options":["Yuki Kajiura","Hiroyuki Sawano","Yasuharu Takanashi","Kenji Kawai"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-composer-018"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail_(TV_series)"},{"question":"Snow Fairy is the first opening of the TV anime. Which group sang it?","options":["SuG","Idoling!!!","Funkist","Back-On"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-openings-first-036"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail_(TV_series)"},{"question":"Which Fairy Tail film premiered in Japan in 2012?","options":["Phoenix Priestess","Dragon Cry","Fairy Tail Zero","100 Years Quest"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-film-1-019","fairy-tail-film-2-020"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'fairy-tail' and site_id = 'anime'), 'Odd One Out: Fairy Tail Spells, Songs and Studios', 'odd-one-out-fairy-tail-spells-songs-and-studios', 'intruder', '[{"question":"Three of these wizards use Dragon Slayer Magic. Which one does not?","options":[{"label":"Erza Scarlet"},{"label":"Natsu Dragneel"},{"label":"Gajeel Redfox"},{"label":"Wendy Marvell"}],"correct":0,"kind":"ability","spoiler":{"arc":8,"scope":"both"},"fact_ids":["fairy-tail-natsu-flame-108","fairy-tail-gajeel-iron-086","fairy-tail-wendy-sky-093","fairy-tail-erza-requip-074"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Three of these acts sang openings of the TV anime. Which one sang an ending instead?","options":[{"label":"Funkist"},{"label":"Shiho Nanba"},{"label":"SuG"},{"label":"BiSH"}],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["fairy-tail-openings-first-036","fairy-tail-openings-last-037","fairy-tail-endings-first-038"],"source_url":"https://en.wikipedia.org/wiki/Fairy_Tail_(TV_series)"},{"question":"Three of these are kinds of magic. Which one is a nickname?","options":[{"label":"Ice Make"},{"label":"Titania"},{"label":"Solid Script"},{"label":"Beast Soul"}],"correct":1,"kind":"ability","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fairy-tail-gray-icemake-071","fairy-tail-levy-script-082","fairy-tail-elfman-soul-079","fairy-tail-erza-titania-073"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fairy_Tail_characters"},{"question":"Three of these studios worked on the final season. Which one worked only on the first season?","options":[{"label":"A-1 Pictures"},{"label":"Satelight"},{"label":"Bridge"},{"label":"CloverWorks"}],"correct":1,"kin