insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'fruits-basket' and site_id = 'anime'), 'Fruits Basket Hard Quiz: Akito''s Secret, Kazuma''s Boy and the Last Season', 'akito-s-secret-kazuma-s-boy-and-the-last-season-fruits-basket-hard-quiz', 'multiple_choice', '[{"question":"What is revealed about Akito in the manga and the 2019 anime?","options":["Akito is not a Sohma by blood","Akito is female but lives as a man","Akito is secretly Kyo''s mother","Akito is secretly Shigure''s sister"],"correct":1,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["fruits-basket-akito-sohma-sex-045"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"How does Akito describe herself in relation to the zodiac?","options":["As its oldest member","As its first victim","As its god and the master of the members'' souls","As its doctor"],"correct":2,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["fruits-basket-akito-sohma-god-044"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Besides Kureno, Hatori and Ayame, which of the oldest zodiac members knew Akito''s secret?","options":["Shigure","Yuki","Momiji","Kyo"],"correct":0,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["fruits-basket-akito-sohma-secret-047"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who takes Kyo in after his mother dies and his father rejects him?","options":["Hatori Sohma","Kazuma Sohma","Shigure Sohma","Ayame Sohma"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fruits-basket-kyo-sohma-childhood-037"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_charac