insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'fruits-basket' and site_id = 'anime'), 'Fruits Basket Characters in Three Clues: Who Is This?', 'fruits-basket-characters-in-three-clues-who-is-this', 'guess_from_clues', '[{"question":"Who is this character?","clues":["She has lost her parents and is still a high school student.","She keeps house for her hosts in exchange for a roof.","A rice ball was her part in the childhood game."],"options":["Arisa Uotani","Tohru Honda","Kisa Sohma","Saki Hanajima"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-tohru-honda-name-030","fruits-basket-tohru-honda-onigiri-031"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who is this character?","clues":["The animal that curses him is a rat.","His older brother is a flamboyant snake.","Nobunaga Shimazaki voices him in the 2019 anime."],"options":["Kyo Sohma","Yuki Sohma","Momiji Sohma","Hatsuharu Sohma"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-yuki-sohma-name-033","fruits-basket-ayame-sohma-name-048","fruits-basket-yuki-sohma-voice-034"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who is this character?","clues":["He is cursed by an animal that is not in the zodiac.","Legend says another animal tricked his animal out of a feast.","Yuma Uchida voices him in the 2019 anime."],"options":["Yuki Sohma","Kyo Sohma","Ayame Sohma","Hatori Sohma"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-kyo-sohma-name-035","fruits-basket-kyo-sohma-legend-036","fruits-basket-kyo-sohma-voice-038"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who is this character?","clues":["He is the owner of the house where the story''s heroine ends up living.","His name is linked to the tenth month, the autumn showers month.","The animal of his month is a dog."],"options":["Hatori Sohma","Shigure Sohma","Ritsu Sohma","Ayame Sohma"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-shigure-sohma-name-040","fruits-basket-shigure-sohma-name-meaning-041"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who is this character?","clues":["This man has very long silver hair.","He is the older brother of a boy admired at school.","His animal form is a snake."],"options":["Hatori Sohma","Ayame Sohma","Hatsuharu Sohma","Shigure Sohma"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-ayame-sohma-name-048"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who is this character?","clues":["He is the dragon of the zodiac, but his animal form is a seahorse.","He looks after the health of the whole family.","He wipes the memories of outsiders who find out the secret."],"options":["Ayame Sohma","Hatori Sohma","Ritsu Sohma","Shigure Sohma"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fruits-basket-hatori-sohma-name-050","fruits-basket-hatori-sohma-doctor-051"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fruits_Basket_characters"},{"question":"Who is this character?","clues":["This boy is the rabbit of the zodiac.","His mother comes from Germany.","Megumi Han voices him in the 2019 anime."],"options":["Hiro Sohma","Momiji Sohma","Kisa Sohma","Hatsuharu Sohma"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fruits-basket-momiji-sohma-name-055","fruits-basket-momiji-sohma-heritage-056","fruits-basket-momiji-sohma-voice-057"],"source_url":"https: