insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_15'), (select id from public.groups where slug = 'fullmetal-alchemist' and site_id = 'anime'), 'Steel and Sums: True or False', 'steel-and-sums-fma-true-or-false', 'true_false', '[{"question":"Hiromu Arakawa wrote and drew the manga all by herself.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"The manga ran in Weekly Shōnen Jump.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"The manga ran in Monthly Shōnen Gangan until June 2010.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"In 2004 the manga won the 49th Shogakukan Manga Award.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-manga-award-006"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"Studio Bones produced the first TV anime, which has 51 episodes.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-anime-2003-run-007"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"Brotherhood has 51 episodes and was shown from 2009 to 2010.","correct":false,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-brotherhood-run-010"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist:_Brotherhood"},{"question":"Seiji Mizushima directed Brotherhood.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-anime-2003-staff-008","fullmetal-alchemist-brotherhood-staff-011"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"The 2003 anime used five opening songs.","correct":false,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-themes-2003-013"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_episodes"},{"question":"Sid sang both the first ending and the last opening of Brotherhood.","correct":true,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-themes-brotherhood-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist:_Brotherhood_episodes"},{"question":"The song Brothers was reused in Brotherhood.","correct":false,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-brothers-song-019"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_15'), (select id from public.groups where slug = 'fullmetal-alchemist' and site_id = 'anime'), 'The Alchemist''s First Lesson: Fullmetal Alchemist Basics', 'the-alchemists-first-lesson-fma-basics', 'multiple_choice', '[{"question":"Who wrote and drew the Fullmetal Alchemist manga all by herself?","options":["Hiromu Arakawa","Masashi Kishimoto","Tite Kubo","Kohei Horikoshi"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"In which magazine did the manga run?","options":["Weekly Shōnen Jump","Weekly Shōnen Magazine","Monthly Shōnen Sirius","Monthly Shōnen Gangan"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"Which company published the manga?","options":["Shueisha","Kodansha","Shogakukan","Square Enix"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"How many collected volumes does the finished story fill?","options":["18","27","24","36"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-volume-count-004"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"Which studio produced the TV anime?","options":["Madhouse","MAPPA","Bones","Wit Studio"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-anime-2003-run-007","fullmetal-alchemist-brotherhood-staff-011"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"How many episodes does Brotherhood run?","options":["26","64","51","100"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-brotherhood-run-010"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist:_Brotherhood"},{"question":"How many episodes did the first TV anime have, shown from 2003 to 2004?","options":["51","26","39","64"],"correct":0,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-anime-2003-run-007"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"In which year did Brotherhood begin broadcasting?","options":["2009","2003","2006","2011"],"correct":0,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-brotherhood-run-010"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist:_Brotherhood"},{"question":"What does the Japanese title Hagane no Renkinjutsushi mean in English?","options":["Alchemist of Steel","Soldier of Bronze","Smith of Silver","Master of Iron"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-japanese-title-001"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"Which pair of networks broadcast the first TV anime?","options":["NHK and TV Asahi","Fuji TV and NTV","MBS and TBS","TV Tokyo and Nippon TV"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-anime-2003-run-007"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_15'), (select id from public.groups where slug = 'fullmetal-alchemist' and site_id = 'anime'), 'Two Anime, One Story: Which Adaptation?', 'two-anime-one-story-fma-adaptations', 'multiple_choice', '[{"question":"After roughly how many episodes did the first anime leave the manga plot?","options":["12","6","25","40"],"correct":0,"kind":"episode","spoiler":{"arc":1,"scope":"anime"},"fact_ids":["fullmetal-alchemist-anime-2003-original-story-009"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"What did Hiromu Arakawa ask for, sending the first anime off on its own?","options":["An original ending","A longer run","A new director","A darker score"],"correct":0,"kind":"arc","spoiler":{"arc":1,"scope":"anime"},"fact_ids":["fullmetal-alchemist-anime-2003-original-story-009"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"Which villain exists only in the 2003 anime, where she is the main antagonist?","options":["Envy","Greed","Dante","Shou Tucker"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"anime"},"fact_ids":["fullmetal-alchemist-dante-anime-only-018"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"How many episodes do the two TV anime have between them?","options":["90","100","130","115"],"correct":3,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["fullmetal-alchemist-arc-structure-015"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"How many opening songs did the 2003 anime use?","options":["Two","Five","Nine","Four"],"correct":3,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-themes-2003-013"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_episodes"},{"question":"Which spelling of the Xing prince''s name do the 2009 anime and Viz''s earliest volumes use, against Lin Yao in the Japanese manga?","options":["Lyn Yao","Ling Yao","Lin Yau","Linn Yaoh"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fullmetal-alchemist-lin-yao-name-020"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Which song, sung in Russian, was never reused in Brotherhood?","options":["Melissa","Brothers","Again","Rain"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-brothers-song-019"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)"},{"question":"How many ending songs did Brotherhood go through?","options":["Two","Four","Five","Nine"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-themes-brotherhood-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist:_Brotherhood_episodes"}]'::jsonb, 'hard', 'published', 8, 'anime', 2, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_15'), (select id from public.groups where slug = 'fullmetal-alchemist' and site_id = 'anime'), 'Which One Is Not a Homunculus? Fullmetal Alchemist Odd One Out', 'which-one-is-not-a-homunculus-fullmetal-alchemist-odd-one-out', 'intruder', '[{"question":"Three of these are homunculi, the artificial beings named after deadly sins. Which one is a human alchemist?","options":[{"label":"Kimblee"},{"label":"Gluttony"},{"label":"Sloth"},{"label":"Lust"}],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fullmetal-alchemist-lust-homunculus-041","fullmetal-alchemist-gluttony-homunculus-042","fullmetal-alchemist-sloth-homunculus-043","fullmetal-alchemist-homunculi-sins-044","fullmetal-alchemist-kimblee-state-alchemist-045"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these are animals. Which one is a soldier?","options":[{"label":"Black Hayate"},{"label":"Maria Ross"},{"label":"Alexander"},{"label":"Xiao Mei"}],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fullmetal-alchemist-black-hayate-dog-046","fullmetal-alchemist-xiao-mei-panda-047","fullmetal-alchemist-alexander-dog-048","fullmetal-alchemist-maria-ross-soldier-049"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these characters are State Alchemists. Which one works in military intelligence instead?","options":[{"label":"Edward Elric"},{"label":"Maes Hughes"},{"label":"Roy Mustang"},{"label":"Alex Louis Armstrong"}],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-edward-youngest-sa-050","fullmetal-alchemist-roy-flame-sa-051","fullmetal-alchemist-armstrong-strong-arm-sa-052","fullmetal-alchemist-hughes-intelligence-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these come from the faraway country of Xing. Which one is an Ishbalan?","options":[{"label":"May Chang"},{"label":"Scar"},{"label":"Lan Fan"},{"label":"Lin Yao"}],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fullmetal-alchemist-lin-yao-xing-prince-054","fullmetal-alchemist-may-chang-xing-princess-055","fullmetal-alchemist-lan-fan-bodyguard-056","fullmetal-alchemist-scar-ishbalan-057"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these men serve in Roy Mustang''s squadron. Which one was sent to guard Edward?","options":[{"label":"Heymans Breda"},{"label":"Vato Falman"},{"label":"Jean Havoc"},{"label":"Denny Brosh"}],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["fullmetal-alchemist-havoc-mustang-team-058","fullmetal-alchemist-breda-mustang-team-059","fullmetal-alchemist-falman-mustang-team-060","fullmetal-alchemist-brosh-guard-061"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these are whole countries. Which one is a small town?","options":[{"label":"Xing"},{"label":"Amestris"},{"label":"Resembool"},{"label":"Drachma"}],"correct":2,"kind":"lore","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fullmetal-alchemist-amestris-country-062","fullmetal-alchemist-xing-country-063","fullmetal-alchemist-drachma-country-064","fullmetal-alchemist-resembool-town-065"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these have their souls bound to armor. Which one is a researcher with no armor at all?","options":[{"label":"Tim Marcoh"},{"label":"Alphonse Elric"},{"label":"Slicer Brothers"},{"label":"Barry the Chopper"}],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fullmetal-alchemist-alphonse-armor-066","fullmetal-alchemist-barry-armor-067","fullmetal-alchemist-slicer-brothers-armor-068","fullmetal-alchemist-marcoh-researcher-069"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these characters wear automail. Which one builds it for a living?","options":[{"label":"Edward Elric"},{"label":"Lan Fan"},{"label":"Winry Rockbell"},{"label":"Buccaneer"}],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fullmetal-alchemist-edward-automail-070","fullmetal-alchemist-lan-fan-automail-071","fullmetal-alchemist-buccaneer-automail-072","fullmetal-alchemist-winry-mechanic-073"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"},{"question":"Three of these were animated by studio Bones. Which one is a live-action film?","options":[{"label":"The Revenge of Scar"},{"label":"The Sacred Star of Milos"},{"label":"Conqueror of Shamballa"},{"label":"Fullmetal Alchemist: Brotherhood"}],"correct":0,"kind":"production","spoiler":{"arc":2,"scope":"both"},"fact_ids":["fullmetal-alchemist-bones-animated-works-074","fullmetal-alchemist-conqueror-shamballa-film-075","fullmetal-alchemist-sacred-star-milos-film-076","fullmetal-alchemist-revenge-of-scar-live-action-077"],"source_url":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist"},{"question":"Three of these characters come from the manga. Which one was borrowed from a light novel for the first anime?","options":[{"label":"Sheska"},{"label":"Rosé Thomas"},{"label":"Pinako Rockbell"},{"label":"Russell Tringham"}],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["fullmetal-alchemist-rose-manga-078","fullmetal-alchemist-pinako-manga-079","fullmetal-alchemist-sheska-librarian-080","fullmetal-alchemist-tringham-light-novel-081"],"source_url":"https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters"}]'::jsonb, 'medium', 'published', 10, 'anime', 2, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'gintama' and site_id = 'anime'), 'Gintama Characters in Three Clues: Who Is This?', 'gintama-characters-in-three-clues-who-is-this', 'guess_from_clues', '[{"question":"Who is this character?","clues":["His voice actor in Japanese is Tomokazu Sugita.","He has naturally wavy hair.","He loves sweets and runs an odd-jobs shop."],"options":["Tatsuma Sakamoto","Shinpachi Shimura","Gintoki Sakata","Isao Kondo"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-gintoki-sakata-name-034","gintama-gintoki-sakata-hair-035","gintama-gintoki-sakata-voice-036"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["He is a comrade of the hero from the war.","His nickname is a word for a hairpiece.","His pet communicates with signboards."],"options":["Tatsuma Sakamoto","Isao Kondo","Kotaro Katsura","Toshiro Hijikata"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-kotaro-katsura-name-046","gintama-kotaro-katsura-zura-047","gintama-elizabeth-signs-045"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["This pet looks like a giant white bird.","It never speaks.","Its owner is a wanted resistance fighter."],"options":["Tama","Sadaharu","Elizabeth","Catherine"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-elizabeth-name-044","gintama-elizabeth-signs-045"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["She comes from a clan of alien fighters.","Her skin is sensitive to the sun.","Her strength is extraordinary."],"options":["Catherine","Tae Shimura","Kagura","Tama"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-kagura-name-039","gintama-kagura-skin-040"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["He is the second in command of a police-like force.","He is rarely seen without a cigarette.","His nickname calls him a demon."],"options":["Sagaru Yamazaki","Isao Kondo","Toshiro Hijikata","Sougo Okita"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-toshiro-hijikata-name-052","gintama-toshiro-hijikata-voice-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["He is the best swordsman of the force he belongs to.","He likes to use a bazooka.","Kenichi Suzumura voices him in Japanese."],"options":["Sagaru Yamazaki","Toshiro Hijikata","Sougo Okita","Isao Kondo"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-sogo-okita-name-054","gintama-sogo-okita-voice-055"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["He is a spy.","He is often caught playing badminton on the job.","He grows fond of a red bean bun."],"options":["Sougo Okita","Isao Kondo","Sagaru Yamazaki","Toshiro Hijikata"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-sagaru-yamazaki-name-056"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["He is the head of the police.","He wears sunglasses.","He thinks that people in sunglasses are assassins."],"options":["Toshiro Hijikata","Isao Kondo","Katakuriko Matsudaira","Taizo Hasegawa"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-katakuriko-matsudaira-name-057"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["She runs the family dojo.","She is the older sister of a Yorozuya member.","Her cooking is terrible."],"options":["Tama","Otose","Tae Shimura","Catherine"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-tae-shimura-name-061"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"},{"question":"Who is this character?","clues":["He is a former official who has fallen on hard times.","His nickname is Madao.","He still wears sunglasses."],"options":["Tatsuma Sakamoto","Isao Kondo","Taizo Hasegawa","Sagaru Yamazaki"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["gintama-taizo-hasegawa-name-062"],"source_url":"https://en.wikipedia.org/wiki/List_of_Gintama_characters"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
