insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'inuyasha' and site_id = 'anime'), 'Inuyasha Quiz: a Well, a Shattered Jewel and a Half-Demon', 'a-well-a-jewel-and-a-half-demon-inuyasha-quiz', 'multiple_choice', '[{"question":"Through which old object does Kagome travel back to the Sengoku period?","options":["A mirror pool","A shrine bell","The Bone Eater''s Well","A mountain cave"],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-premise-016"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"Inuyasha is the son of which two parents?","options":["A fox demon and a monk","A dog demon and a human","Two human warriors","A wolf demon and a priestess"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-inuyasha-name-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"What breaks into fragments that the heroes set out to gather?","options":["The Tessaiga","The Wind Tunnel","The Bone Eater","The Shikon Jewel"],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-shards-017"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"What is the greatest weapon of Miroku?","options":["A sacred arrow","The Wind Tunnel","A bead necklace","A bone boomerang"],"correct":1,"kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-miroku-wind-tunnel-059"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"What weapon does Sango throw?","options":["A huge bone boomerang","A giant hammer","A pair of claws","A spiked fan"],"correct":0,"kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-sango-boomerang-062"],"source