insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'inuyasha' and site_id = 'anime'), 'Real or Made Up: Feudal Era Facts from Inuyasha', 'real-or-made-up-feudal-era-facts-from-inuyasha', 'true_false', '[{"question":"Kagome falls into a well at her family shrine and lands in the Sengoku period.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-premise-016"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"The mother of Inuyasha is a demon and his father is a human.","correct":false,"fun_fact":"His father was a dog demon and his mother was human.","kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-inuyasha-name-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Sango fights with a huge bone boomerang.","correct":true,"kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-sango-boomerang-062"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"The manga was serialized in Weekly Shonen Jump.","correct":false,"fun_fact":"It ran in Weekly Shonen Sunday.","kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["inuyasha-magazine-003"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"Kaede is the younger sister of Kikyo.","correct":true,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-kaede-name-074"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"The first anime series has 100 episodes.","correct":false,"fun_fact":"It has 167 episodes.","kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["inuyasha-episodes-028"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"The villain of the second film is Kaguya, a character based on the Tale of the Bamboo Cutter.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["inuyasha-film-2-042"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"The Wind Tunnel curse of Miroku was laid on his grandfather by Sesshomaru.","correct":false,"fun_fact":"Naraku laid the curse.","kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-miroku-wind-tunnel-059"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Inuyasha earned a Shogakukan Manga Award in 2002.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["inuyasha-award-shogakukan-019"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha"},{"question":"Toei Animation produced the first anime series.","correct":false,"fun_fact":"Sunrise produced it.","kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["inuyasha-anime-studio-025"],"source_url":"https://en.wikipedia.org/wiki/Inuyasha_(TV_series)"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'inuyasha' and site_id = 'anime'), 'Who Is This? Inuyasha Characters in Three Clues', 'who-is-this-inuyasha-character-in-three-clues', 'guess_from_clues', '[{"question":"Who is this character?","clues":["Kappei Yamaguchi gives this person a voice.","The mother was human and the father a dog demon.","A soft side hides under a lot of pride."],"options":["Inuyasha","Shippo","Sesshomaru","Miroku"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-inuyasha-name-053","inuyasha-inuyasha-voice-054"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["This modern girl is the reincarnation of an ancient priestess.","Archery becomes a strong skill.","Satsuki Yukino gives this person a voice."],"options":["Kagome Higurashi","Kaede","Sango","Kikyo"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-kagome-higurashi-name-055","inuyasha-kagome-higurashi-archery-056","inuyasha-kagome-higurashi-voice-057"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["A Buddhist monk who is clever but lecherous.","A black hole sits in the right palm.","Kōji Tsujitani gives this person a voice."],"options":["Miroku","Naraku","Inuyasha","Sesshomaru"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-miroku-name-058","inuyasha-miroku-wind-tunnel-059","inuyasha-miroku-voice-060"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["The most skilled demon slayer of the village that first held the jewel.","The age is sixteen.","The weapon is a purified bone boomerang."],"options":["Sango","Kaede","Kagome Higurashi","Kikyo"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-sango-name-061","inuyasha-sango-boomerang-062","inuyasha-sango-voice-063"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["An orphan who is a young fox demon.","At first this child tried to steal the jewel.","The reason was to avenge a father."],"options":["Shippo","Miroku","Kirara","Inuyasha"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-shippo-name-064"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["The companion of a demon slayer.","Small like a kitten, with two tails.","Able to grow big enough to carry several passengers through the air."],"options":["Kirara","Inuyasha","Shippo","Sesshomaru"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-kirara-name-065"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["A powerful demon feared throughout the feudal era.","This person is the older half-brother of the hero.","Ken Narita gives this person a voice."],"options":["Sesshomaru","Miroku","Inuyasha","Naraku"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-sesshomaru-name-066","inuyasha-sesshomaru-voice-067"],"source_url":"https://en.wikipedia.org/wiki/List_of_Inuyasha_characters"},{"question":"Who is this character?","clues":["The main villain of the story.","A half-demon who began as a bandit.","Toshiyuki Morikawa gives this person a voice."],"options":["Naraku","Inuyasha","Sesshomaru","Miroku"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["inuyasha-naraku-name-068","inuyasha-naraku-voice-069"],"so