insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_25'), (select id from public.groups where slug = 'kagurabachi' and site_id = 'anime'), 'Swords and Sorcerers: Kagurabachi Odds and Ends', 'swords-and-sorcerers-kagurabachi-odds-and-ends', 'multiple_choice', '[{"question":"How many years after the end of the Seitei War does the story take place?","options":["8 years","12 years","18 years","25 years"],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kagurabachi-setting-war-010"],"source_url":"https://en.wikipedia.org/wiki/Kagurabachi"},{"question":"What is the Kamunabi in the story?","options":["A rival clan of swordsmiths","A state-run organization of sorcerers","A black market auction house","A school for young blade bearers"],"correct":1,"kind":"lore","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kagurabachi-kamunabi-agency-012"],"source_url":"https://en.wikipedia.org/wiki/Kagurabachi"},{"question":"About how many page views did the series have on Manga Plus by April 2024?","options":["Over 9 million","Over 29 million","Over 99 million","Over 199 million"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kagurabachi-page-views-011"],"source_url":"https://en.wikipedia.org/wiki/Kagurabachi"},{"question":"Who writes and draws Kagurabachi?","options":["Yukinobu Tatsu","Takeru Hokazono","Naoya Matsumoto","Tatsuki Fujimoto"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kagurabachi-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Kagurabachi"},{"question":"Which secret seventh Enchanted Blade does Chihiro carry, made by his father?","options":["Tobimune","Enten","Magatsumi","Isou"],"correct":1,"kind":"ability","spoiler":{"arc":1,"scope":"manga"},"fact_ids":["kagurabachi-enten-blade-013"],"source_url":