insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime'), 'Real or Made Up: Love War Facts from Shuchiin Academy', 'real-or-made-up-love-war-facts-from-shuchiin-academy', 'true_false', '[{"question":"Every chapter of the manga is officially called a battle.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaguya-sama-love-is-war-battles-009"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaguya-sama:_Love_Is_War_chapters"},{"question":"Kaguya is the treasurer of the student council.","correct":false,"fun_fact":"Kaguya is the vice president; Yu is the treasurer.","kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-kaguya-shinomiya-name-049"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaguya-sama:_Love_Is_War_characters"},{"question":"Miyuki has a paralyzing fear of insects, especially cockroaches.","correct":true,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-miyuki-shirogane-bugs-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaguya-sama:_Love_Is_War_characters"},{"question":"The manga was first published in Weekly Shonen Jump.","correct":false,"fun_fact":"It started in Miracle Jump and later moved to Weekly Young Jump.","kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["kaguya-sama-love-is-war-manga-start-005","kaguya-sama-love-is-war-magazine-003"],"source_url":"https://en.wikipedia.org/wiki/Kaguya-sama:_Love_Is_War"},{"question":"The names of the characters come from the Tale of the Bamboo Cutter.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-names-011"],"source_url":"https://en.wikipedia.o