insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'kaguya-sama-love-is-war' and site_id = 'anime'), 'Kaguya-sama Hard Quiz: the Shinomiya Clan, a Bamboo Emperor and a Last Film', 'the-shinomiya-clan-a-bamboo-emperor-and-a-last-film-kaguya-sama-hard-quiz', 'multiple_choice', '[{"question":"Which family business does Mikado Shijo stand to inherit?","options":["The Shirogane Works","The Fujiwara Group","The Shijo Group","The Shinomiya Group"],"correct":2,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-mikado-shijo-name-085"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaguya-sama:_Love_Is_War_characters"},{"question":"Which best friend of Nagisa is the older twin sister of Mikado?","options":["Nagisa Kashiwagi","Moeha Fujiwara","Maki Shijo","Kobachi Osaragi"],"correct":2,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-mikado-shijo-name-085","kaguya-sama-love-is-war-maki-shijo-name-074"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaguya-sama:_Love_Is_War_characters"},{"question":"Mikado shares his name with the emperor of which story?","options":["Tale of the Heike","Tale of the Bamboo Cutter","Tales of Ise","Tale of Genji"],"correct":1,"kind":"lore","spoiler":{"arc":4,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-mikado-shijo-namesake-088"],"source_url":"https://en.wikipedia.org/wiki/List_of_Kaguya-sama:_Love_Is_War_characters"},{"question":"Who is the eldest child of Gan''an and the heir to the Shinomiya Group?","options":["Mikado Shijo","Un''yo Shinomiya","Miyuki Shirogane","Oko Shinomiya"],"correct":3,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["kaguya-sama-love-is-war-oko-shinomiya-name-084"],"source_url":"ht