insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_09'), (select id from public.groups where slug = 'my-hero-academia' and site_id = 'anime'), 'Which One Does Not Belong? My Hero Academia Odd One Out', 'which-one-does-not-belong-my-hero-academia-odd-one-out', 'intruder', '[{"question":"Three of these students are in Class 1-A. Which one is in Class 1-B?","options":[{"label":"Tenya Ida"},{"label":"Tsuyu Asui"},{"label":"Momo Yaoyorozu"},{"label":"Itsuka Kendo"}],"correct":3,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["my-hero-academia-tsuyu-class-1a-100","my-hero-academia-momo-class-1a-101","my-hero-academia-tenya-class-1a-102","my-hero-academia-kendo-class-1b-103"],"source_url":"https://en.wikipedia.org/wiki/List_of_My_Hero_Academia_characters"},{"question":"Three of these heroes teach at U.A. Which one is a Pro Hero who does not?","options":[{"label":"Cementoss"},{"label":"Fat Gum"},{"label":"Present Mic"},{"label":"Midnight"}],"correct":1,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["my-hero-academia-present-mic-teacher-104","my-hero-academia-midnight-teacher-105","my-hero-academia-cementoss-teacher-106","my-hero-academia-fat-gum-intern-107"],"source_url":"https://en.wikipedia.org/wiki/List_of_My_Hero_Academia_characters"},{"question":"Three of these Quirks belong to students of Class 1-A. Which one belongs to their homeroom teacher?","options":[{"label":"Half-Cold Half-Hot"},{"label":"Erasure"},{"label":"Zero Gravity"},{"label":"Engine"}],"correct":1,"kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["my-hero-academia-ochaco-zero-gravity-108","my-hero-academia-shoto-half-cold-109","my-hero-academia-tenya-engine-110","my-hero-academia-aizawa-erasure-111"],"source_url":"https://en.wikipedia.org/wiki/List_of_My_Hero_Academia_character