insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_04'), (select id from public.groups where slug = 'naruto' and site_id = 'anime'), 'Naruto From Zero: A Friendly Start', 'naruto-from-zero-the-friendly-start', 'multiple_choice', '[{"question":"Who wrote and drew the Naruto manga?","options":["Eiichiro Oda","Masashi Kishimoto","Tite Kubo","Hajime Isayama"],"correct":1,"fun_fact":"Masashi Kishimoto both wrote and drew the Naruto manga himself.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-authors-002"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"In which magazine did the Naruto manga run?","options":["Weekly Shonen Jump","Weekly Shonen Magazine","Monthly Shonen Gangan","Weekly Young Jump"],"correct":0,"fun_fact":"It ran in Weekly Shonen Jump, published by Shueisha.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"For about how many years did the Naruto manga run in Weekly Shonen Jump?","options":["Fifteen years","Five years","Ten years","Twenty years"],"correct":0,"fun_fact":"Naruto ran from late September 1999 to mid November 2014.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-run-004"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Which studio animated the Naruto TV anime?","options":["Madhouse","Bones","MAPPA","Studio Pierrot"],"correct":3,"fun_fact":"Studio Pierrot made Naruto and Naruto: Shippuden, directed by Hayato Date.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"How many episodes does the first TV series, simply called Naruto, have?","options":["135","500","220","720"],"correct":2,"fun_fact":"Studio Pierrot made it, directed by Hayato Date.","kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"In which year did the Naruto manga start in Weekly Shonen Jump?","options":["1997","1999","2002","2004"],"correct":1,"fun_fact":"It ran for about fifteen years, until mid November 2014.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-run-004"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"In which year did the first Naruto anime begin airing in Japan?","options":["1999","2004","2007","2002"],"correct":3,"fun_fact":"Naruto, the first series, has 220 episodes and aired from 2002 to 2007.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"What is the title of the second Naruto anime series?","options":["Naruto: Blazing Wind","Naruto: Leaf Legends","Naruto: Next Chapter","Naruto: Shippuden"],"correct":3,"fun_fact":"The manga itself is written NARUTO -ナルト- in Japanese.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-titles-001"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Which of these titles belongs to the Naruto franchise?","options":["Bleach: Thousand-Year Blood War","Black Clover","Boruto: Two Blue Vortex","Fairy Tail"],"correct":2,"fun_fact":"The franchise includes Naruto, Naruto: Shippuden and the Boruto titles.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-franchise-009"],"source_url":"https://naruto-official.com/en"},{"question":"In which year did Naruto: Shippuden finish its run on TV?","options":["2012","2017","2014","2020"],"correct":1,"fun_fact":"Shippuden ran from 2007 to 2017 and has 500 episodes.","kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-shippuden-007"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_04'), (select id from public.groups where slug = 'naruto' and site_id = 'anime'), 'Naruto: Openings, Endings and the Studio', 'naruto-openings-endings-and-the-studio', 'multiple_choice', '[{"question":"Which song opened Naruto: Shippuden for its first thirty episodes?","options":["Haruka Kanata","Blue Bird","Closer","Hero''s Come Back!!"],"correct":3,"fun_fact":"It opened Shippuden from episode 1 to 30.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-first-shippuden-opening-027"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Which group performed Hero''s Come Back!!, the first Shippuden opening?","options":["nobodyknows+","HOUND DOG","FLOW","Ikimonogakari"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-first-shippuden-opening-027"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Which artist performed the very first Naruto opening, used for episodes 1 to 25?","options":["HOUND DOG","FLOW","Sambomaster","Snowkel"],"correct":0,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which singer performed two endings of the first series, Wind and Yellow moon?","options":["Rythem","Akeboshi","Orange Range","TiA"],"correct":1,"fun_fact":"Wind opened the run of endings, and Yellow moon came much later.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-akeboshi-endings-028"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which band performed the openings GO!!!, Re:member and Sign?","options":["Asian Kung-Fu Generation","Ikimonogakari","FLOW","Nico Touches the Walls"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018","naruto-themes-op-part-two-019"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which opening accompanied episodes 154 to 178 of the first series?","options":["Re:member","Namikaze Satellite","Yura Yura","No Boy, No Cry"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Which group performed the third ending, Viva Rock ~japanese side~?","options":["Rythem","Orange Range","Raigo","Akeboshi"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-ed-part-one-020"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Who performed the first ending of Shippuden, Nagareboshi ~Shooting Star~?","options":["supercell","Home Made Kazoku","Aqua Timez","Nico Touches the Walls"],"correct":1,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-ed-part-two-a-021"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Who directed both Naruto TV series?","options":["Tetsuro Araki","Shinichiro Watanabe","Hayato Date","Hiroyuki Imaishi"],"correct":2,"fun_fact":"Hayato Date is the director of both Naruto TV series from Studio Pierrot.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006","naruto-tv-shippuden-007"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Who designed the characters for the Naruto anime?","options":["Masashi Kishimoto","Yoshiyuki Sadamoto","Tetsuya Nishio","Hirohiko Araki"],"correct":2,"fun_fact":"Tetsuya Nishio designed the characters for the anime because Kishimoto himself asked for him.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-character-designer-024"],"source_url":"https://en.wikipedia.org/wiki/Naruto"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_04'), (select id from public.groups where slug = 'naruto' and site_id = 'anime'), 'Naruto True or False: Ninja Edition', 'naruto-true-or-false-ninja-edition', 'true_false', '[{"question":"Masashi Kishimoto both wrote and drew the Naruto manga.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-authors-002"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"The manga is written NARUTO -ナルト- in Japanese.","correct":true,"fun_fact":"Its second anime series is titled Naruto: Shippuden.","kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-titles-001"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Diver, an opening of Naruto: Shippuden, was performed by Joe Inoue.","correct":false,"fun_fact":"Diver was by Nico Touches the Walls. Joe Inoue sang Closer.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-two-019"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_%E7%96%BE%E9%A2%A8%E4%BC%9D"},{"question":"Naruto: Shippuden has 220 episodes.","correct":false,"fun_fact":"Shippuden has 500 episodes. The first series has 220.","kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-shippuden-007"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"The second opening of Naruto was Haruka Kanata by Asian Kung-Fu Generation.","correct":true,"fun_fact":"Haruka Kanata accompanied episodes 26 to 53.","kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-themes-op-part-one-018"],"source_url":"https://ja.wikipedia.org/wiki/NARUTO_-%E3%83%8A%E3%83%AB%E3%83%88-_(%E3%82%A2%E3%83%8B%E3%83%A1)"},{"question":"Madhouse is the studio that made t