insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_27'), (select id from public.groups where slug = 'omniscient-readers-viewpoint' and site_id = 'anime'), 'Which Came First? Omniscient Reader''s Viewpoint From Novel to Film', 'which-came-first-omniscient-readers-viewpoint-from-novel-to-film', 'multiple_choice', '[{"question":"Which Omniscient Reader milestone is the oldest of these four?","options":["The live-action film opened in South Korean cinemas","Season 1 ended on the Naver Webtoon","The first English volume of the comic reached readers","The original web novel started on Munpia"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-season-one-finale-008","omniscient-readers-viewpoint-film-release-011","omniscient-readers-viewpoint-novel-run-004","omniscient-readers-viewpoint-english-comic-vol1-029"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"Which Omniscient Reader milestone is the newest of these four?","options":["The webtoon adaptation went live on Naver","The first English volume of the comic reached readers","The original web novel started on Munpia","English readers got the webtoon"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-novel-run-004","omniscient-readers-viewpoint-english-webtoon-007","omniscient-readers-viewpoint-webtoon-launch-006","omniscient-readers-viewpoint-english-comic-vol1-029"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"Which of these four events happened before the other three?","options":["The live-action film opened in South Korean cinemas","Season 1 ended on the Naver Webtoon","The first English volume of the novel was printed","The first English volume of the comic reached readers"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-film-release-011","omniscient-readers-viewpoint-english-novel-vol1-030","omniscient-readers-viewpoint-english-comic-vol1-029","omniscient-readers-viewpoint-season-one-finale-008"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"Which of these four events happened after the other three?","options":["The webtoon adaptation went live on Naver","The first English volume of the comic reached readers","Season 1 ended on the Naver Webtoon","English readers got the webtoon"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-season-one-finale-008","omniscient-readers-viewpoint-english-comic-vol1-029","omniscient-readers-viewpoint-webtoon-launch-006","omniscient-readers-viewpoint-english-webtoon-007"],"source_url":"https://zh.wikipedia.org/wiki/%E5%85%A8%E7%9F%A5%E8%AE%80%E8%80%85%E8%A6%96%E8%A7%92"},{"question":"Put these four in order: which one comes at the start of the line?","options":["English readers got the webtoon","The live-action film opened in South Korean cinemas","The first English volume of the comic reached readers","The first English volume of the novel was printed"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["omniscient-readers-viewpoint-english-novel-vol1-030","omniscient-readers-viewpoint-english-comic-vol1-029","omniscient-readers-viewpoint-film-release-011","omniscient-readers-viewpoint-english-webtoon-007"],"source_url":"https://en.wikipedia.org/wiki/Omniscient_Reader%27s_Viewpoint"},{"question":"Put these four in order: which one comes at the end of the line?","options":["The first English volume of the novel was printed","The webtoon adaptation went live on Naver","English readers got the webtoon","The first English volume of the comic reached readers"],"correct":0,"kind":"manga","spoiler":{