insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_02'), (select id from public.groups where slug = 'one-piece' and site_id = 'anime'), 'Pirate''s Honor: One Piece True or False', 'pirates-honor-one-piece-true-or-false', 'true_false', '[{"question":"Eiichiro Oda is the one person behind both the writing and the drawing of the One Piece manga.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"Shueisha has run the manga in Weekly Shōnen Jump since the summer of 1999.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-magazine-run-003"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"By the start of July 2026 Shueisha had put out 115 collected volumes of the manga.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-piece-manga-volumes-004"],"source_url":"https://en.wikipedia.org/wiki/One_Piece"},{"question":"From April 2026 the anime has aired in four split cours each year.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-piece-semi-seasonal-format-024"],"source_url":"https://en.wikipedia.org/wiki/List_of_One_Piece_episodes"},{"question":"Season 5 of the home media release is titled TV Original, because its 13 episodes are new stories made for the anime.","correct":true,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["one-piece-tv-original-season-029"],"source_url":"https://en.wikipedia.org/wiki/List_of_One_Piece_episodes"},{"question":"Guinness World Records recognized Oda in 2015 and 2022 for the longest running anime.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["one-pi