insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_19'), (select id from public.groups where slug = 'oshi-no-ko' and site_id = 'anime'), 'Three Seasons in the Spotlight: The Timeline', 'three-seasons-in-the-spotlight-the-timeline', 'multiple_choice', '[{"question":"Aqua and Ruby are reborn twins. Which doctor was Aqua in his past life?","options":["Gorou Amamiya","Taishi Gotanda","Ichigo Saitō","Melt Narushima"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["oshi-no-ko-twins-past-lives-018"],"source_url":"https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters"},{"question":"Which patient was Ruby in her past life?","options":["Kana Arima","Akane Kurokawa","MEM-cho","Sarina Tendōji"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["oshi-no-ko-twins-past-lives-018"],"source_url":"https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters"},{"question":"How many episodes did the second season run?","options":["11","12","24","13"],"correct":3,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["oshi-no-ko-anime-season-two-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_episodes"},{"question":"On which date did the second season begin?","options":["July 3, 2024","April 12, 2023","January 14, 2026","October 6, 2024"],"correct":0,"kind":"episode","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["oshi-no-ko-anime-season-two-010"],"source_url":"https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_episodes"},{"question":"Which act performs Fatal, the opening of season two?","options":["Gemn","YOASOBI","Chanmina","Natori"],"correct":0,"kind":"music","spoiler":{"arc":2,"scope":"anime"},"fact_ids":["oshi-no-ko-themes-season-two-013"],"source_url":"https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)"},{"que