insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 're-zero' and site_id = 'anime'), 'Odd One Out: Re:Zero Candidates, Cult Leaders and Openings', 'odd-one-out-re-zero-candidates-cult-leaders-and-openings', 'intruder', '[{"question":"Three of these are candidates in the royal election. Which one is a knight instead?","options":[{"label":"Crusch Karsten"},{"label":"Priscilla Barielle"},{"label":"Anastasia Hoshin"},{"label":"Reinhard van Astrea"}],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["re-zero-candidates-030","re-zero-character-name-042"],"source_url":"https://en.wikipedia.org/wiki/List_of_Re:Zero_characters"},{"question":"Three of these stand for a sin in the Witch Cult or among the Witches. Which one does not?","options":[{"label":"Petelgeuse Romanée-Conti"},{"label":"Reinhard van Astrea"},{"label":"Regulus Corneas"},{"label":"Satella"}],"correct":1,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["re-zero-character-name-053","re-zero-character-name-057","re-zero-character-name-054","re-zero-character-name-042"],"source_url":"https://en.wikipedia.org/wiki/List_of_Re:Zero_characters"},{"question":"Three of these people worked on the anime as director or composer. Which one wrote the original novels?","options":[{"label":"Masaharu Watanabe"},{"label":"Tappei Nagatsuki"},{"label":"Masahiro Shinohara"},{"label":"Kenichiro Suehiro"}],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["re-zero-director-first-014","re-zero-director-now-013","re-zero-composer-015","re-zero-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"Three of these acts sang openings. Which one only sang endings?","options":[{"label":"Konomi Suzuki"},