insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 're-zero' and site_id = 'anime'), 'Re:Zero Timeline: Which Came First?', 're-zero-timeline-which-came-first', 'multiple_choice', '[{"question":"Which of these four Re:Zero works came out first?","options":["The first light novel volume","The second season","The OVA Memory Snow","The first season"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["re-zero-light-novel-004","re-zero-anime-s2-008","re-zero-ova-017","re-zero-anime-s1-007"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"Among these, which release was the most recent as of early 2025?","options":["The first season","The second season","The third season","The OVA The Frozen Bond"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["re-zero-anime-s1-007","re-zero-anime-s2-008","re-zero-anime-s3-009","re-zero-ova-017"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"Which of these debuted in 2019?","options":["The OVA Memory Snow","The second season","The third season","The OVA The Frozen Bond"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["re-zero-ova-017","re-zero-anime-s2-008","re-zero-anime-s3-009"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"The story was online before it was ever printed. Which of these came first?","options":["The first light novel volume","The first season","The web novel","The OVA Memory Snow"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["re-zero-web-novel-003","re-zero-light-novel-004","re-zero-anime-s1-007","re-zero-ova-017"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero"},{"question":"Which of these four arrived last, after all the others?","options":["The first light novel volume","The first season","The OVA Memory Snow","The second season"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["re-zero-light-novel-004","re-zero-anime-s1-007","re-zero-ova-017","re-zero-anime-s2-008"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"After the 2020 episodes of the second season, which of these aired next?","options":["The first part of the third season","The second part of the third season","The second part of the second season","The first part of the fourth season"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["re-zero-anime-s2-008","re-zero-anime-s3-009","re-zero-anime-s4-010"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"Which of these four chapters of the anime aired most recently?","options":["The first part of the third season","The first part of the fourth season","The second part of the third season","The second part of the second season"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["re-zero-anime-s2-008","re-zero-anime-s3-009","re-zero-anime-s4-010"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"Which of these debuted before any TV season after the first?","options":["The second season","The third season","The fourth season","The OVA Memory Snow"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["re-zero-ova-017","re-zero-anime-s2-008","re-zero-anime-s3-009","re-zero-anime-s4-010"],"source_url":"https://en.wikipedia.org/wiki/Re:Zero_(TV_series)"},{"question":"Which of these four parts was the last to air?","options":["The first part of the second season","The second part of the second season","The first part of the third season","The second part of the third season"],"correct":3,"kind":"production","spoiler":{