insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 're-zero' and site_id = 'anime'), 'Re:Zero Hard Quiz: Witches of Sin, Cult Leaders and the Cost of Return by Death', 'witches-of-sin-cult-leaders-and-the-cost-of-return-by-death-re-zero-hard-quiz', 'multiple_choice', '[{"question":"How has Roswaal L. Mathers lived far longer than he looks?","options":["By drinking spirit blood","By possessing his descendants","By sleeping inside crystals","By trading years with witches"],"correct":1,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["re-zero-roswaal-ages-075"],"source_url":"https://en.wikipedia.org/wiki/List_of_Re:Zero_characters"},{"question":"Whom does Roswaal hope to revive, as his master and the love of his life?","options":["Satella","Beatrice","Rem","Echidna"],"correct":3,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["re-zero-roswaal-echidna-076"],"source_url":"https://en.wikipedia.org/wiki/List_of_Re:Zero_characters"},{"question":"What is Puck''s true identity?","options":["The Sage of the Grand Cascade","The Beast of the End of the Eternally Frozen Lands","The Dragon of the royal capital","The Spirit of the Sanctuary"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["re-zero-puck-true-062"],"source_url":"https://en.wikipedia.org/wiki/List_of_Re:Zero_characters"},{"question":"What is it about Subaru that makes Rem hate him at first?","options":["A bad joke about Ram","A stolen insignia","A scent of the Witch","A rumor about the mansion"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["re-zero-rem-hate-068"],"source_url":"https://en.wikipedia.org/wiki/List_of_Re:Zero_characters"},{"question":"Satella, the figure worshipped by the Witch Cult