insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'sakamoto-days' and site_id = 'anime'), 'Sakamoto Days Quiz: a Retired Hitman, a Convenience Store and One Rule', 'a-retired-hitman-a-convenience-store-and-one-rule-sakamoto-days-quiz', 'multiple_choice', '[{"question":"What was the title of the one-shot that Yuto Suzuki published in Jump Giga before the series began?","options":["Sakamoto","Convenience Killer","Taro Days","The Fat Hitman"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["sakamoto-days-oneshot-005"],"source_url":"https://en.wikipedia.org/wiki/Sakamoto_Days"},{"question":"What kind of business does the retired hero run?","options":["A flower shop","A ramen shop","A bookstore","A convenience store"],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-premise-011"],"source_url":"https://en.wikipedia.org/wiki/Sakamoto_Days"},{"question":"What condition did Aoi set for dating Sakamoto?","options":["He must lose weight","He must never kill again","He must move abroad","He must change his name"],"correct":1,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-no-kill-012"],"source_url":"https://en.wikipedia.org/wiki/Sakamoto_Days"},{"question":"Which power gives Shin his nickname, the Clairvoyant?","options":["Reading minds","Seeing the future","Controlling fire","Moving objects"],"correct":0,"kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-shin-asakura-name-048"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"What is the name of the parrot that works as the spotter of Heisuke?","options":["Pippo","Kuroko","Piisuke","Tamago"],"correct":2,"kind":"character","spoiler":{"arc"