insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'sakamoto-days' and site_id = 'anime'), 'Sakamoto Days Hard Quiz: the JAA, a Reindeer Mask and a Final Battle', 'the-jaa-a-reindeer-mask-and-a-final-battle-sakamoto-days-hard-quiz', 'multiple_choice', '[{"question":"On which date did the Sakamoto Days manga begin its serialization?","options":["November 21, 2020","December 26, 2019","January 11, 2025","April 2, 2021"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["sakamoto-days-manga-start-006"],"source_url":"https://en.wikipedia.org/wiki/Sakamoto_Days"},{"question":"How many episodes did the first season of the anime run for across its two cours?","options":["22","24","13","26"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["sakamoto-days-episodes-035"],"source_url":"https://en.wikipedia.org/wiki/Sakamoto_Days"},{"question":"Which two names does the serial killer hunting assassins go by?","options":["Ten and Sloth","Zero and Slate","X and Slur","Y and Slash"],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["sakamoto-days-kei-uzuki-name-075"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"For whom does the Order member Kanaguri secretly work?","options":["Takamura","Dondenkai","X","The JCC"],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["sakamoto-days-kanaguri-name-070"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"What kind of mask does the cyborg Kashima wear?","options":["A rabbit mask","A fox mask","A tiger mask","A reindeer mask"],"correct":3,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["sakamoto-days-