insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'sakamoto-days' and site_id = 'anime'), 'Who Is This? Sakamoto Days Characters in Three Clues', 'who-is-this-sakamoto-days-character-in-three-clues', 'guess_from_clues', '[{"question":"Who is this character?","clues":["Tomokazu Sugita gives this person a voice.","Only thirty percent of the former strength remains.","In extreme moments the fat disappears and the power doubles."],"options":["Yoichi Nagumo","Heisuke Mashimo","Shishiba","Taro Sakamoto"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-taro-sakamoto-name-045","sakamoto-days-taro-sakamoto-forms-046","sakamoto-days-taro-sakamoto-voice-047"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["A former hitman who is 21 years old.","Each time the boss pictures a murder, this person senses it.","Nobunaga Shimazaki plays this role."],"options":["Heisuke Mashimo","Hyo","Yoichi Nagumo","Shin Asakura"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-shin-asakura-name-048","sakamoto-days-shin-asakura-gag-049","sakamoto-days-shin-asakura-voice-050"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["The father of this 18 year old led a crime syndicate.","The fighting style blends Tai Chi and Drunken Fist.","Ayane Sakura gives this person a voice."],"options":["Aoi Sakamoto","Osaragi","Hana Sakamoto","Lu Xiaotang"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-lu-xiaotang-name-051","sakamoto-days-lu-xiaotang-style-052","sakamoto-days-lu-xiaotang-voice-053"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["This hitman is a sniping specialist.","A bird acts as the spotter.","Ryōta Suzuki plays this role."],"options":["Shishiba","Yoichi Nagumo","Hyo","Heisuke Mashimo"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-heisuke-mashimo-name-057","sakamoto-days-heisuke-mashimo-parrot-058","sakamoto-days-heisuke-mashimo-voice-059"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["An old classmate and colleague of the hero.","Disguising himself as other people is a specialty.","Natsuki Hanae plays this role."],"options":["Shishiba","Heisuke Mashimo","Hyo","Yoichi Nagumo"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-yoichi-nagumo-name-060","sakamoto-days-yoichi-nagumo-voice-061"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["A member of the Order who is strict and cynical.","The one food that this person hates is a bulb vegetable.","The weapon of choice is a hammer."],"options":["Hyo","Osaragi","Yoichi Nagumo","Shishiba"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-shishiba-name-062"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["The Order''s youngest member.","Snacks are a great love.","Saori Hayami plays this role."],"options":["Aoi Sakamoto","Hana Sakamoto","Lu Xiaotang","Osaragi"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["sakamoto-days-osaragi-name-063","sakamoto-days-osaragi-voice-064"],"source_url":"https://en.wikipedia.org/wiki/List_of_Sakamoto_Days_characters"},{"question":"Who is this character?","clues":["This member of the Order is harsh.