insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'slam-dunk' and site_id = 'anime'), 'Slam Dunk Hard Quiz: Sannoh, a Red Monkey and 500 Threes a Day', 'sannoh-a-red-monkey-and-500-threes-a-day-slam-dunk-hard-quiz', 'multiple_choice', '[{"question":"Who is the calm captain and point guard of Sannoh?","options":["Kenji Fujima","Shinichi Maki","Eiji Sawakita","Kazunari Fukatsu"],"correct":3,"kind":"character","spoiler":{"arc":8,"scope":"both"},"fact_ids":["slam-dunk-kazunari-fukatsu-name-082"],"source_url":"https://en.wikipedia.org/wiki/List_of_Slam_Dunk_characters"},{"question":"Which Sannoh star is regarded as the finest all-round high school player in Japan?","options":["Nobunaga Kiyota","Eiji Sawakita","Akira Sendoh","Masashi Kawata"],"correct":1,"kind":"character","spoiler":{"arc":8,"scope":"both"},"fact_ids":["slam-dunk-eiji-sawakita-name-083"],"source_url":"https://en.wikipedia.org/wiki/List_of_Slam_Dunk_characters"},{"question":"Which Sannoh player ranks as the best high school center in the country?","options":["Masashi Kawata","Toru Hanagata","Takenori Akagi","Jun Uozumi"],"correct":0,"kind":"character","spoiler":{"arc":8,"scope":"both"},"fact_ids":["slam-dunk-masashi-kawata-name-084"],"source_url":"https://en.wikipedia.org/wiki/List_of_Slam_Dunk_characters"},{"question":"Who taught Sawakita to play basketball from the age of four?","options":["A neighbor","His coach","His older brother","His father"],"correct":3,"kind":"character","spoiler":{"arc":8,"scope":"both"},"fact_ids":["slam-dunk-eiji-sawakita-name-083"],"source_url":"https://en.wikipedia.org/wiki/List_of_Slam_Dunk_characters"},{"question":"Which Kainan player built his deadly three point shot by taking 500 every day after practice?","options":["Shinichi Maki","Soichiro Ji