insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_03'), (select id from public.groups where slug = 'spy-x-family' and site_id = 'anime'), 'A Fake Family on Day One: Spy x Family Basics', 'a-fake-family-on-day-one-spy-x-family-basics', 'multiple_choice', '[{"question":"Who both writes and draws the Spy x Family manga?","options":["Kazuhiro Furuhashi","Yukiko Imai","Tatsuya Endo","Takahiro Harada"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["spy-x-family-manga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family"},{"question":"By April 2026, circulation of the manga had climbed past how many copies?","options":["12 million","24 million","42 million","84 million"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["spy-x-family-copies-in-print-012"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family"},{"question":"How many collected volumes had the manga filled by April 2026?","options":["12","21","25","17"],"correct":3,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["spy-x-family-manga-volumes-004"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family"},{"question":"Which two studios share the animation of the Spy x Family anime?","options":["Wit Studio and MAPPA","Wit Studio and CloverWorks","CloverWorks and Madhouse","MAPPA and Madhouse"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["spy-x-family-anime-studios-005"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)"},{"question":"Which channel aired the three seasons of the Spy x Family anime?","options":["NHK General TV","TV Tokyo","Nippon Television","Kodansha"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["spy-x-family-anime-run-007"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)"},{"question":"How many episodes do the three seasons of the anime add up to?","options":["37","25","74","50"],"correct":3,"kind":"episode","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["spy-x-family-anime-run-007"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)"},{"question":"What is the gift that lets Anya see through the secret jobs of both of her new parents?","options":["Telepathy","Time travel","Invisibility","Super strength"],"correct":0,"kind":"ability","spoiler":{"arc":0,"scope":"both"},"fact_ids":["spy-x-family-anya-telepath-013"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family"},{"question":"Where does Yor work by day?","options":["Berlint General Hospital","Eden Academy","City Hall","Ministry of Foreign Affairs"],"correct":2,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["spy-x-family-yor-thorn-princess-014"],"source_url":"https://en.wikipedia.org/wiki/List_of_Spy_%C3%97_Family_characters"},{"question":"Who is the handler who oversees Loid''s mission, Operation Strix?","options":["Fiona Frost","Franky Franklin","Yor Forger","Sylvia Sherwood"],"correct":3,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["spy-x-family-operation-strix-020"],"source_url":"https://en.wikipedia.org/wiki/List_of_Spy_%C3%97_Family_characters"},{"question":"In which year did the theatrical film Code: White reach Japanese cinemas?","options":["2023","2019","2021","2025"],"correct":0,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["spy-x-family-code-white-film-016"],"source_url":"https://en.wikipedia.org/wiki/Spy_%C3%97_Family"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = exc