insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'that-time-i-got-reincarnated-as-a-slime' and site_id = 'anime'), 'Who Is This Monster? Reincarnated as a Slime in Three Clues', 'who-is-this-monster-reincarnated-as-a-slime-in-three-clues', 'guess_from_clues', '[{"question":"Who is this?","clues":["This being was locked away in a cave for centuries.","The same being is one of the four original True Dragons and is called the Storm Dragon.","This dragon swaps names with a slime."],"options":["Milim Nava","Ranga","Veldora Tempest","Geld"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-veldora-seal-025","that-time-i-got-reincarnated-as-a-slime-character-name-042","that-time-i-got-reincarnated-as-a-slime-names-026"],"source_url":"https://en.wikipedia.org/wiki/That_Time_I_Got_Reincarnated_as_a_Slime_(TV_series)"},{"question":"Who is this?","clues":["This hobgoblin looks smaller and sillier than the others.","This hobgoblin leads the goblin riders.","A hidden talent for swordplay makes this goblin a competent fighter."],"options":["Gobta","Gabil","Geld","Kurobe"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-043","that-time-i-got-reincarnated-as-a-slime-gobta-riders-064"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This beast first meets Rimuru while raiding a goblin village.","This beast chooses to serve Rimuru instead of avenging a dead father.","After being named, this wolf evolves into a Tempest Star Wolf."],"options":["Gobta","Geld","Ranga","Gabil"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-044","that-time-i-got-reincarnated-as-a-slime-ranga-star-065"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This warrior is a prince.","The village of this prince was wiped out by orcs.","After being named, this ogre evolves into a kijin."],"options":["Souei","Kurobe","Geld","Benimaru"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-benimaru-prince-066","that-time-i-got-reincarnated-as-a-slime-character-name-045"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This ogre is one of the six survivors of a ruined village.","This ogre cooks terribly.","This ogre is the self-appointed secretary and bodyguard of Rimuru."],"options":["Shuna","Shion","Souei","Kurobe"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-046","that-time-i-got-reincarnated-as-a-slime-shion-cook-067"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This ogre is the sister of Benimaru.","This ogre teaches the goblins how to sew.","Rimuru gave this princess the title Holy Princess."],"options":["Shion","Shuna","Souei","Gabil"],"correct":1,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-047","that-time-i-got-reincarnated-as-a-slime-shuna-title-069"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This ogre is a buddy of the ogre prince.","This ogre has abilities like those of a ninja.","Rimuru named this scout with the title Spy."],"options":["Souei","Kurobe","Gobta","Geld"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-048","that-time-i-got-reincarnated-as-a-slime-souei-title-070"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This large ogre is the least featured of his companions.","Rimuru gave this ogre the title Blacksmith.","This ogre swings a giant mallet and forges Tempest''s tools."],"options":["Kurobe","Souei","Benimaru","Gabil"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-049","that-time-i-got-reincarnated-as-a-slime-kurobe-title-071"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This being is the daughter of the True Dragon Veldanava.","The same being is the niece of Veldora.","This carefree Demon Lord is known as the Destroyer."],"options":["Ramiris","Shizue Izawa","Milim Nava","Gabil"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-052","that-time-i-got-reincarnated-as-a-slime-milim-destroyer-074"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"},{"question":"Who is this?","clues":["This fairy is a former Spirit Queen.","This fairy is known as the Labyrinth Master.","This fairy loves manga with Veldora."],"options":["Milim Nava","Shizue Izawa","Ramiris","Shuna"],"correct":2,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["that-time-i-got-reincarnated-as-a-slime-character-name-053","that-time-i-got-reincarnated-as-a-slime-ramiris-labyrinth-076"],"source_url":"https://en.wikipedia.org/wiki/List_of_That_Time_I_Got_Reincarnated_as_a_Slime_characters"}]'::jsonb, 'medium', 'published', 10, 'anime', 1, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'tokyo-ghoul' and site_id = 'anime'), 'Tokyo Ghoul Quiz: Anteiku, Kaneki and Young Jump', 'anteiku-kaneki-and-young-jump-tokyo-ghoul-quiz', 'multiple_choice', '[{"question":"Which magazine published the original Tokyo Ghoul manga?","options":["Weekly Shōnen Jump","Weekly Young Jump","Weekly Shōnen Sunday","Monthly Afternoon"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["tokyo-ghoul-manga-run-003"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"},{"question":"What is the name of the coffee shop whose ghoul staff take Kaneki in?","options":["Anteiku","Aogiri Tree","Cochlea","Rushima"],"correct":0,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tokyo-ghoul-anteiku-022"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"},{"question":"Which actor plays Kaneki in the 2017 live-action film?","options":["Kento Yamazaki","Takeru Satoh","Ryunosuke Kamiki","Masataka Kubota"],"correct":3,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tokyo-ghoul-film-cast-017"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul_(film)"},{"question":"Which nickname belongs to the fashionable ghoul Tsukiyama?","options":["The Reaper","The Raven","The Gourmet","The Serpent"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tokyo-ghoul-character-detail-077"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Ghoul_characters"},{"question":"Whose organs are transplanted into Kaneki after the accident on their date?","options":["Touka Kirishima","Rize Kamishiro","Hinami Fueguchi","Akira Mado"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tokyo-ghoul-character-detail-057"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Ghoul_characters"},{"question":"Which song plays over the opening of the first season?","options":["Asphyxia","Katharsis","Unravel","Munou"],"correct":2,"kind":"music","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["tokyo-ghoul-theme-op-027"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"},{"question":"How many volumes does the original manga fill?","options":["12","14","16","18"],"correct":1,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["tokyo-ghoul-manga-size-004"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"},{"question":"What do the letters CCG stand for in Tokyo Ghoul?","options":["Council of Ghoul Control","Committee for Ghoul Containment","Corps of Ghoul Capture","Commission of Counter Ghoul"],"correct":3,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tokyo-ghoul-ccg-023"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"},{"question":"Which company publishes the manga in English in North America?","options":["Viz Media","Dark Horse Comics","Yen Press","Kodansha USA"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["tokyo-ghoul-manga-english-026"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"},{"question":"Which prequel spin-off manga first appeared on the Jump Live service?","options":["Tokyo Ghoul: Days","Tokyo Ghoul:re","Tokyo Ghoul [Jack]","Tokyo Ghoul: Zakki"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["tokyo-ghoul-prequel-manga-018"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Ghoul"}]'::jsonb, 'easy', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_