insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'tokyo-revengers' and site_id = 'anime'), 'Tokyo Revengers Hard Quiz: Bonten, Bloody Halloween and the Final Rewrite', 'bonten-bloody-halloween-and-the-final-rewrite-tokyo-revengers-hard-quiz', 'multiple_choice', '[{"question":"Who killed Mikey''s older brother Shinichiro while trying to steal a motorbike with Baji?","options":["Shuji Hanma","Haruki Hayashida","Tetta Kisaki","Kazutora Hanemiya"],"correct":3,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["tokyo-revengers-kazutora-past-075"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Why does Baji seem to defect to Valhalla?","options":["To protect Mikey''s sister","To repay a debt to Hanma","To learn more about Kisaki","To escape the rules of the gang"],"correct":2,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["tokyo-revengers-baji-defect-069"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Revengers"},{"question":"What does Kisaki finally confess as his motive?","options":["A debt owed to Izana","Revenge for a lost brother","A promise made to Draken","Ambition and a fixation on Hinata"],"correct":3,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["tokyo-revengers-kisaki-motive-068"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Revengers"},{"question":"Who resents Mikey out of jealousy over the legacy of Shinichiro?","options":["Izana Kurokawa","Taiju Shiba","Kazutora Hanemiya","Shuji Hanma"],"correct":0,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["tokyo-revengers-izana-jealous-080"],"source_url":"https://en.wikipedia.org/wiki/Tokyo_Revengers"},{"question":"Who murders Emma Sano before the Tenjiku conflict?