insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'tokyo-revengers' and site_id = 'anime'), 'Tokyo Revengers Delinquents in Three Clues: Who Is This?', 'tokyo-revengers-delinquents-in-three-clues-who-is-this', 'guess_from_clues', '[{"question":"Who is this delinquent?","clues":["This delinquent commands a gang that goes by Toman for short.","The same delinquent befriends Takemichi after seeing his resolve.","Everyone calls this leader by the nickname Mikey."],"options":["Manjiro Sano","Ken Ryuguji","Takashi Mitsuya","Masataka Kiyomizu"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-035","tokyo-revengers-mikey-nick-058","tokyo-revengers-toman-023"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this delinquent?","clues":["This delinquent is the second-in-command of the Tokyo Manji Gang.","A stabbing by Kiyomasa nearly kills this delinquent in the first timeline.","This friend of Mikey is known for a mature, big-brother attitude."],"options":["Manjiro Sano","Takashi Mitsuya","Naoto Tachibana","Ken Ryuguji"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-036","tokyo-revengers-draken-stab-062","tokyo-revengers-draken-nick-060"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This person was Takemichi''s sweetheart in middle school.","The death of this person is what sends Takemichi back in time.","This person has a younger brother who becomes a police officer."],"options":["Emma Sano","Yuzuha Shiba","Hinata Tachibana","Haruki Hayashida"],"correct":2,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["tokyo-revengers-hinata-role-064","tokyo-revengers-naoto-police-066"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This character is Hinata''s younger brother.","In the new present this character works as a police officer.","A handshake with this character triggers the time leaps."],"options":["Ken Ryuguji","Takashi Mitsuya","Masataka Kiyomizu","Naoto Tachibana"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-038","tokyo-revengers-naoto-police-066","tokyo-revengers-takemichi-leap-055"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this delinquent?","clues":["This bully treats Takemichi like a servant.","Underground fights are this bully''s business.","This bully stabs Draken, and answers to the nickname Kiyomasa."],"options":["Shuji Hanma","Haruki Hayashida","Takashi Mitsuya","Masataka Kiyomizu"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-043","tokyo-revengers-kiyomasa-fights-072","tokyo-revengers-draken-stab-062"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This captain is a founding member of the Tokyo Manji Gang.","This captain seems to switch sides to Valhalla.","A spin-off manga carries a letter from this captain in its title."],"options":["Chifuyu Matsuno","Keisuke Baji","Takashi Mitsuya","Kazutora Hanemiya"],"correct":1,"kind":"character","spoiler":{"arc":2,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-040","tokyo-revengers-baji-defect-069","tokyo-revengers-baji-letter-018"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This delinquent captains the third division.","This captain turns himself in to the police.","Fans know this captain by the nickname Pah-chin."],"options":["Haruki Hayashida","Takashi Mitsuya","Masataka Kiyomizu","Shuji Hanma"],"correct":0,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-042","tokyo-revengers-pahchin-captain-071"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This gang leader runs the tenth generation of the Black Dragons.","The younger siblings of this leader are Hakkai and Yuzuha.","This leader abuses his siblings after their mother''s death."],"options":["Taiju Shiba","Hakkai Shiba","Kazutora Hanemiya","Shuji Hanma"],"correct":0,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-047","tokyo-revengers-taiju-abuse-077"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This fighter is one of the Four Heavenly Kings of Tenjiku.","This fighter is nicknamed The Brawler.","A large scar and a half-blind eye mark this fighter."],"options":["Izana Kurokawa","Haruchiyo Sanzu","Kakucho","Shuji Hanma"],"correct":2,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-050","tokyo-revengers-kakucho-brawler-081"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"},{"question":"Who is this?","clues":["This delinquent is a vice-captain of the fifth division.","This delinquent has long hair.","A mask never leaves this delinquent''s face."],"options":["Shuji Hanma","Izana Kurokawa","Haruchiyo Sanzu","Kakucho"],"correct":2,"kind":"character","spoiler":{"arc":4,"scope":"both"},"fact_ids":["tokyo-revengers-character-name-053","tokyo-revengers-sanzu-mask-083"],"source_url":"https://en.wikipedia.org/wiki/List_of_Tokyo_Revengers_characters"}]'::jsonb, 'medium', 'published', 10, 'anime', 4, 'both') on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_20'), (select id from public.groups where slug = 'tower-of-god' and site_id = 'anime'), 'Climber''s Check: Tower of God True or False', 'climbers-check-tower-of-god-true-or-false', 'true_false', '[{"question":"The creator writes and draws the series under the pen name S.I.U., and his real name is Lee Jong-hui.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"The webtoon began on Kakao Page on June 30, 2010.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-webtoon-launch-003"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"Rankers are the climbers who reach the top of the Tower.","correct":true,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-regulars-irregulars-018"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"Kazuyoshi Takeuchi was the chief director of season two.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"anime"},"fact_ids":["tower-of-god-anime-staff-010"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"The official English translation arrived through Line Webtoon from July 2019.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-english-release-006"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"Season one ran for 26 episodes in 2020.","correct":false,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-anime-season-one-008"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God_season_1"},{"question":"Telecom Animation Film made season two of the anime.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-anime-season-one-008","tower-of-god-anime-season-two-009"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God_season_1"},{"question":"Kevin Penkin wrote the music for both seasons.","correct":true,"kind":"music","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-anime-staff-010"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"Shinsu gets weaker and thinner on the higher floors of the Tower.","correct":false,"kind":"lore","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-shinsu-017"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"},{"question":"The creator lines up major events and characters long before they appear, sometimes more than eight years ahead.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["tower-of-god-long-term-planning-020"],"source_url":"https://en.wikipedia.org/wiki/Tower_of_God"}]'::jsonb, 'medium', 'published', 10, 'anime', 0, null) on conflict (slug) do update set creator_id = excluded.creator_id, group_id = excluded.group_id, title = excluded.title, quiz_type = excluded.quiz_type, questions = excluded.questions, difficulty = excluded.difficulty, status = excluded.status, question_count = excluded.question_count, site_id = excluded.site_id, spoiler_arc_ord = excluded.spoiler_arc_ord, spoiler_scope = excluded.spoiler_scope where quizzes.site_id = 'anime';
