insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_30'), (select id from public.groups where slug = 'vinland-saga' and site_id = 'anime'), 'Skald or Liar: Vinland Saga True or False', 'skald-or-liar-vinland-saga-true-or-false', 'true_false', '[{"question":"Makoto Yukimura writes and draws the manga, which Kodansha publishes.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["vinland-saga-creator-002"],"source_url":"https://en.wikipedia.org/wiki/Vinland_Saga_(manga)"},{"question":"The manga began in Monthly Afternoon in April 2005.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["vinland-saga-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Vinland_Saga_(manga)"},{"question":"The manga finished in Monthly Afternoon on July 25, 2025.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["vinland-saga-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Vinland_Saga_(manga)"},{"question":"The story is collected in 29 volumes holding 200 chapters.","correct":false,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["vinland-saga-volumes-chapters-004"],"source_url":"https://en.wikipedia.org/wiki/List_of_Vinland_Saga_chapters"},{"question":"The last volume came out on September 22, 2025.","correct":true,"kind":"manga","spoiler":{"arc":0,"scope":"manga"},"fact_ids":["vinland-saga-volumes-chapters-004"],"source_url":"https://en.wikipedia.org/wiki/List_of_Vinland_Saga_chapters"},{"question":"The manga article divides the plot into three arcs.","correct":false,"kind":"arc","spoiler":{"arc":0,"scope":"both"},"fact_ids":["vinland-saga-story-arcs-009"],"source_url":"https://en.wikipedia.org/wiki/Vinland_Saga_(manga)"},{"question":"The War Arc fills chapters 1 to 54 and the Slav