insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'otakuquiz_team'), (select id from public.groups where slug = 'violet-evergarden' and site_id = 'anime'), 'Violet Evergarden Hard Quiz: Gilbert''s Brooch, Clara''s Letters and an Island', 'gilberts-brooch-clara-s-letters-and-an-island-violet-evergarden-hard-quiz', 'multiple_choice', '[{"question":"On which date did Violet Evergarden: The Movie premiere in Japan?","options":["September 6, 2019","September 18, 2020","July 4, 2018","January 10, 2020"],"correct":1,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["violet-evergarden-movie-release-022"],"source_url":"https://en.wikipedia.org/wiki/Violet_Evergarden:_The_Movie"},{"question":"Whom does Violet tutor at a girls'' boarding school in the side story film?","options":["Isabella York","Charlotte Abelfreyja Drossel","Anne Magnolia","Taylor Bartlett"],"correct":0,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["violet-evergarden-eternity-plot-021"],"source_url":"https://en.wikipedia.org/wiki/Violet_Evergarden:_Eternity_and_the_Auto_Memory_Doll"},{"question":"What does the terminally ill Clara Magnolia ask Violet to prepare for her daughter?","options":["A portrait of the family","A new doll","A farewell speech","A set of letters to be read later"],"correct":3,"kind":"character","spoiler":{"arc":1,"scope":"both"},"fact_ids":["violet-evergarden-clara-magnolia-name-063","violet-evergarden-clara-magnolia-illness-064"],"source_url":"https://en.wikipedia.org/wiki/Violet_Evergarden"},{"question":"What was the name of Isabella York before she joined the York family?","options":["Taylor Bartlett","Erica Brown","Anne Magnolia","Amy Bartlett"],"correct":3,"kind":"character","spoiler":{"arc":3,"scope":"both"},"fact_ids":["violet-evergarden-isabella-york-past-066"],"source_url":"h